window.DOSIK=window.DOSIK||{};DOSIK["nm_labor1"]={"1":[{"t":"table","title":"근로의 권리와 의무","head":["항목","내용"],"rows":[["근로의 권리 주체·내용","근로의 권리는 자연인의 권리이고 법인은 주체가 될 수 없다 · 일할 환경에 관한 권리도 근로의 권리에 들어간다 · 국가에 대한 직접적인 직장존속보장청구권은 인정되지 않으므로 근로관계 당연승계 입법 의무도 없다"],["국가의 노력·시행 의무","국가는 사회적·경제적 방법으로 고용의 증진과 적정임금의 보장에 노력하여야 하고, 법률이 정하는 바에 따라 최저임금제를 시행하여야 한다 · 적정임금 보장의 주체는 국가이며 ‘사용자’로 바꾼 선지가 출제됐다"],["근로조건 기준·근로의 의무","근로조건의 기준은 인간의 존엄성을 보장하도록 법률로 정한다 · 모든 국민은 근로의 의무를 지고, 국가는 근로의 의무의 내용과 조건을 민주주의원칙에 따라 법률로 정한다 · 기출은 두 문장의 주어를 ‘근로의 권리’로 바꿔 틀린 선지로 냈다"],["여자·연소자·유가족","여자의 근로는 특별한 보호를 받고 고용·임금·근로조건에서 부당한 차별을 받지 않는다 · 연소자의 근로도 특별한 보호를 받는다 · 국가유공자·상이군경 및 전몰군경의 유가족이 우선적으로 근로의 기회를 받으며 ‘전몰군경’ 본인이나 ‘근로의 의무’로 바꾸면 틀린다"]]},{"t":"table","title":"법원 사이의 효력","head":["항목","내용"],"rows":[["근로기준법 미달 근로계약","그 부분에 한정하여 무효이고 전부 무효가 아니다"],["근로기준법 미달 단체협약","신법 우선과 관계없이 무효다"],["취업규칙과 근로계약","취업규칙보다 유리한 근로계약은 우선 적용되고, 집단적 동의로 불리하게 바뀐 취업규칙도 개별 동의가 없으면 기존의 유리한 근로계약을 누르지 못한다"],["ILO 협약","한국은 2021년 제87호(결사의 자유), 제98호(단결권·단체교섭), 제29호(강제노동) 협약을 비준했다 · 제105호(강제노동 철폐)는 비준하지 않았으므로 국내 법원이 아니다"],["고시","행정기관 내부의 사무처리준칙에 그치는 고시는 법원으로 보지 않는다"]]},{"t":"table","title":"근로기준법의 적용 범위","head":["항목","내용"],"rows":[["적용 범위","상시 5명 이상의 근로자를 사용하는 모든 사업에 적용되고 영리 여부나 1회적 사업인지는 묻지 않는다 · 국가와 지방자치단체에도 적용된다 · 동거하는 친족만을 사용하는 사업과 가사 사용인에게는 적용하지 않는다"],["4명 이하·초단시간 특칙","상시 4명 이하 사업에도 근로조건 명시(제17조)는 적용되지만 연차 유급휴가(제60조)와 공휴일 유급 보장은 적용되지 않는다 · 4주 평균 1주 소정근로시간이 15시간 미만인 근로자에게는 주휴일과 연차 유급휴가가 적용되지 않는다 · 토지의 경작 등 농림 사업 근로자에게는 근로시간·휴게·휴일 규정을 적용하지 않는다"],["총칙상 의무","근로관계 당사자는 근로기준법의 기준을 이유로 근로조건을 낮출 수 없다 · 누구든지 법률에 따르지 않고 영리로 남의 취업에 개입하거나 중간인으로서 이익을 취득하지 못한다 · 공민권 행사에 필요한 시간을 청구받으면 거부하지 못하고, 직무 수행에 지장이 없는 범위에서 청구한 시간을 변경할 수 있을 뿐이다"]]}],"2":[{"t":"table","title":"근로조건 명시","head":["항목","내용"],"rows":[["근로조건 명시","임금, 소정근로시간, 주휴일, 연차 유급휴가 등은 근로계약 체결 때 명시하고 임금의 구성항목·계산방법·지급방법, 소정근로시간, 휴일, 연차휴가는 서면으로 교부한다 · 체결 후 이 사항을 변경할 때에도 명시하여야 한다 · 18세 미만인 자와 계약하면 근로조건을 서면으로 명시하여 교부한다"],["명시 위반의 효과","명시된 근로조건이 사실과 다르면 근로자는 손해배상을 청구할 수 있고 즉시 근로계약을 해제할 수 있다 · 손해배상 청구는 노동위원회에 신청할 수도 있다"],["미성년자 근로계약","친권자나 후견인은 미성년자의 근로계약을 대리할 수 없고, 미성년자 동의가 있어도 마찬가지다 · 친권자, 후견인 또는 고용노동부장관은 근로계약이 미성년자에게 불리하다고 인정하면 해지할 수 있다"]]},{"t":"vs","title":"채용내정과 시용","cols":[{"name":"채용내정","items":["해약권이 유보된 근로계약이 성립하므로 내정 취소에도 해고 제한(제23조)이 적용된다","내정 취소가 무효이면 내정자는 취업하였다면 받았을 임금을 청구할 수 있다"]},{"name":"시용","items":["시용기간 중에도 확정적 근로관계는 존재하고 사용자에게 해약권이 유보되어 있을 뿐이다","본계약 거부는 보통의 해고보다 넓게 인정되지만 객관적으로 합리적인 이유와 사회통념상 상당성이 필요하다","시용기간을 명시하지 않았으면 정식 사원으로 채용된 것으로 본다","만료 시 ‘기간 만료’ 통지만 한 거부는 서면 통지 절차의 하자로 효력이 없다"]}]},{"t":"table","title":"명부·증명서","head":["항목","내용"],"rows":[["근로자 명부·서류 보존","사용기간 30일 미만인 일용근로자는 근로자 명부를 작성하지 않을 수 있다(기출 X 선지는 ‘3개월 미만’) · 명부 기재사항이 바뀌면 지체 없이 정정한다 · 근로계약서, 임금대장, 고용·해고 서류 등은 3년간 보존하고, 임금대장은 마지막으로 써 넣은 날부터, 근로계약서는 근로관계가 끝난 날부터 기산한다"],["사용증명서·취업방해 금지","계속하여 30일 이상 근무한 근로자는 퇴직 후 3년 이내에 사용증명서를 청구할 수 있고 사용자는 사실대로 적어 즉시 내준다 · 누구든지 취업을 방해할 목적으로 비밀 기호나 명부를 작성·사용하거나 통신을 하지 못한다"]]},{"t":"table","title":"단시간근로자와 위약 예정 금지","head":["항목","내용"],"rows":[["단시간근로자 근로조건","1일 소정근로시간 수는 4주 동안의 소정근로시간을 그 기간의 통상근로자 총 소정근로일 수로 나눈 시간이다(분모를 ‘단시간근로자의 소정근로일 수’로 바꾼 선지가 나왔다) · 연차휴가 임금은 시간급, 출산전후휴가 임금은 일급 통상임금이 기준이다 · 초과근로는 합의한 경우에만 시킬 수 있다 · 단시간근로자에게만 적용되는 취업규칙을 불리하게 바꾸려면 그 단시간근로자 과반수의 동의를 받는다"],["위약예정·전차금 상계 금지","근로계약 불이행에 대한 위약금이나 손해배상액을 예정하는 계약은 금지된다 · 전차금이나 근로를 조건으로 한 전대채권과 임금을 상계하지 못하고, 강제 저축이나 저축금 관리 계약도 금지된다 · 노무 제공 중 생명·신체를 해치지 않도록 보호할 의무는 근로계약에 따르는 신의칙상 부수적 의무다"]]}],"3":[{"t":"table","title":"임금 지급 원칙","head":["항목","내용"],"rows":[["임금 지급 4원칙","임금은 통화로 직접 근로자에게 전액을 매월 1회 이상 일정한 날짜를 정하여 지급한다 · 법령이나 단체협약에 특별한 규정이 있으면 임금 일부를 공제하거나 통화 이외의 것으로 지급할 수 있다 · 연봉제도 매월 지급 원칙이 적용되고, 임시 임금과 1개월을 넘는 기간의 출근 성적에 따른 정근수당 등은 예외다"],["직접 지급·임금채권 양도","근로자의 대리인에게 임금을 지급하면 직접불 원칙 위반이다 · 근로자가 임금채권을 양도했더라도 사용자는 양수인에게 지급할 수 없고 양수인도 사용자에게 직접 청구하지 못한다"],["전액 지급과 상계","사용자는 대출금이나 불법행위 손해배상채권으로 임금채권과 상계하지 못한다 · 초과지급된 임금의 반환채권으로 하는 상계와 근로자의 자유로운 의사에 따른 동의가 객관적으로 인정되는 상계는 허용된다 · 임금 대신 사용자의 제3자 채권을 양도하기로 한 약정은 원칙적으로 무효다"],["비상시 지급","근로자가 출산, 질병, 재해, 혼인, 사망 등 비상한 경우의 비용에 쓰려고 청구하면 지급기일 전이라도 이미 제공한 근로에 대한 임금을 지급한다 · 본인의 혼인 비용도 해당한다"]]},{"t":"table","title":"평균임금과 통상임금","head":["항목","내용"],"rows":[["평균임금 산정","산정사유 발생일 이전 3개월 동안 지급된 임금 총액을 그 기간의 총일수로 나눈 금액이다(분모를 ‘총 근로시간 수’로 바꾼 선지가 나왔다) · 산출액이 통상임금보다 적으면 통상임금을 평균임금으로 한다 · 일용근로자의 평균임금은 고용노동부장관이 정하는 금액으로 하고, 지급의무가 확정된 경영평가성과급은 평균임금에 들어간다"],["평균임금 제외 기간","산정기간에 수습기간, 사용자 귀책 휴업기간, 출산전후휴가 기간, 업무상 부상·질병 요양기간, 육아휴직 기간, 쟁의행위 기간 등이 있으면 그 기간과 그 기간 중 받은 임금을 각각 뺀다 · 출산전후휴가 기간을 산정기간에 포함한다는 선지는 틀렸다"],["통상임금","소정근로의 대가로 정기적·일률적으로 지급하기로 정한 임금이고, 대법원은 2024년 전원합의체에서 고정성을 요건에서 뺐다 · 1개월을 넘는 주기로 정기 지급되어도 통상임금이 될 수 있다 · 소정근로시간을 넘는 근로의 대가와 주휴수당은 통상임금이 아니며, 통상임금 제외 합의는 법 기준에 미달하는 범위에서 무효다"]]},{"t":"table","title":"휴업수당과 체불사업주 명단","head":["항목","내용"],"rows":[["휴업수당","사용자 귀책사유로 휴업하면 평균임금의 100분의 70 이상을 지급하고, 그 금액이 통상임금을 넘으면 통상임금을 줄 수 있다 · 부득이한 사유로 사업 계속이 불가능하면 노동위원회의 승인을 받아 70% 미만을 줄 수 있다 · 휴업수당도 임금이고, 근로 의사가 있는데 취업이 거부된 경우와 경영상 대기발령도 휴업에 포함된다"],["체불사업주 명단 공개","고용노동부장관은 명단 공개 전에 3개월 이상의 기간을 정하여 소명 기회를 준다 · 명단은 3년간 게시하며 1년이 아니다 · 법인이면 대표자의 성명·나이·주소와 법인의 명칭·주소를 공개하고, 체불자료를 받은 종합신용정보집중기관은 이를 신용도 판단에 쓸 수 있다"]]}],"4":[{"t":"table","title":"법정근로시간과 탄력적 근로시간제","head":["항목","내용"],"rows":[["법정근로시간·특례","근로시간은 1주 40시간, 1일 8시간이고 당사자 합의로 1주 12시간까지 연장할 수 있다 · 근로자대표와 서면 합의하면 12시간을 넘는 연장과 휴게 변경이 가능한 특례업종은 육상운송(노선버스 제외)·수상운송·항공운송·기타 운송관련 서비스·보건업의 5개다 · 금융보험업은 특례에서 빠졌다(2018 개정)"],["2주 이내 단위","취업규칙으로 정하고 특정 주 48시간을 넘지 못하며 특정 일의 한도 규정은 없다"],["3개월 이내 단위","근로자대표와 서면 합의로 정하고 특정 주 52시간, 특정 일 12시간이 한도다"],["3개월을 넘는 단위","6개월 이내이며 근로일 사이 11시간 연속 휴식을 보장하고, 15세 이상 18세 미만자와 임신 중인 여성에게는 탄력적 근로시간제를 적용하지 않는다"]]},{"t":"vs","title":"선택적 근로시간제와 재량근로","cols":[{"name":"선택적 근로시간제","items":["취업규칙으로 시작·종료 시각을 근로자 결정에 맡긴 근로자를 대상으로 근로자대표와 서면 합의하여 도입하고 표준근로시간을 정한다","정산기간은 1개월 이내, 신상품·신기술 연구개발 업무는 3개월 이내다","18세 이상 임신 중인 여성에게도 적용할 수 있다","임금보전방안 강구 의무는 탄력적 근로시간제에만 있다"]},{"name":"재량근로","items":["근로자대표와 서면 합의로 정한 시간을 근로한 것으로 본다","대상 업무는 신상품·신기술 연구개발, 정보처리시스템 설계·분석, 기사 취재·편집, 디자인·고안, 방송 프로듀서·감독, 회계·법률·특허·감정평가 등 사무다"]}]},{"t":"table","title":"휴게·휴일·가산임금","head":["항목","내용"],"rows":[["휴게·휴일","근로시간이 4시간이면 30분 이상, 8시간이면 1시간 이상의 휴게를 근로시간 도중에 준다 · 1주 소정근로일을 개근하면 1주 평균 1회 이상 유급휴일을 주며 일요일로 정해야 하는 것은 아니다 · 관공서 공휴일(일요일 제외)은 유급으로 보장하되 근로자대표와 서면 합의하면 특정한 근로일로 대체할 수 있다"],["가산임금·보상휴가","연장근로와 야간근로(오후 10시~오전 6시)에는 통상임금의 100분의 50 이상을 가산한다 · 휴일근로는 8시간 이내 100분의 50, 8시간 초과분은 100분의 100 이상을 가산하고, 기준은 평균임금이 아니라 통상임금이다 · 근로자대표와 서면 합의하면 연장·야간·휴일근로 임금 대신 휴가를 줄 수 있고 고용노동부장관 승인은 필요 없다"],["근로시간 규정 적용 제외","농림·축산·수산업 종사자, 고용노동부장관 승인을 받은 감시·단속적 근로자, 사업 종류와 관계없이 관리·감독 또는 기밀 업무 종사자에게는 근로시간·휴게·휴일 규정을 적용하지 않는다 · 감시·단속적 근로는 서면 합의가 아니라 장관 승인이 요건이다 · 야간근로 가산과 연차휴가 규정은 이들에게도 적용된다"]]},{"t":"table","title":"연차휴가","head":["항목","내용"],"rows":[["연차휴가 일수","1년간 80% 이상 출근하면 15일을 준다 · 계속근로 1년 미만이거나 1년간 80% 미만 출근한 근로자에게는 1개월 개근 시 1일을 준다 · 3년 이상 계속근로하면 최초 1년을 넘는 2년마다 1일을 더하고 총 일수는 25일이 한도다"],["연차 출근 간주·수당·대체","업무상 부상·질병 휴업기간, 출산전후휴가 기간, 육아휴직 기간은 출근한 것으로 본다 · 연차휴가권은 1년 근로를 마친 다음 날 생기고, 사용 전에 퇴직해도 미사용 수당 청구권은 남으며 소멸시효는 3년이다 · 근로자대표와 서면 합의하면 연차휴가일을 갈음하여 특정 근로일에 휴무시킬 수 있다"]]}],"5":[{"t":"table","title":"해고와 징계","head":["항목","내용"],"rows":[["해고의 정당한 이유","취업규칙의 해고사유에 해당하더라도 해고에는 정당한 이유가 있어야 한다 · 해고는 묵시적 의사표시로도 할 수 있고, 근로자의 사직 의사표시는 원칙적으로 근로계약을 끝내는 해약고지로 본다 · 해고사유와 시기는 서면으로 알려야 하지만 상시 4명 이하 사업에는 이 서면통지 규정이 적용되지 않는다"],["징계 양정","같은 정도의 비위에 대해 기준과 어긋나게 과중한 징계를 하면 위법이다 · 징계사유로 삼지 않은 비위라도 평소 소행·근무성적·전후 비위 사실은 양정 참작자료가 된다 · 여러 징계사유 중 일부만 인정되어도 나머지로 징계가 타당하면 유효하고, 그 증명책임은 사용자에게 있다"],["징계 사유·절차","사생활의 비행도 기업의 사회적 평가를 해칠 염려가 있으면 징계사유가 된다 · 소명 기회를 주면 충분하고 소명 자체나 개별 혐의마다 질문·진술이 반드시 있어야 하는 것은 아니며, 출석 통보는 소명을 준비할 상당한 기간을 두고 한다 · 무자격위원이 참여한 징계의결은 그를 빼고 정족수가 되어도 무효이고, 원 징계 절차의 하자는 재심에서 보완되면 치유된다"],["노조 합의 조항·감급 제한","노조 간부 징계에 노조와 합의하도록 단체협약에 정했다면 합의 없이 한 징계는 원칙적으로 무효다 · 감급 1회 금액은 평균임금 1일분의 2분의 1을, 총액은 1임금지급기 임금 총액의 10분의 1을 넘지 못한다"]]},{"t":"table","title":"인사·전직과 경영상 해고","head":["항목","내용"],"rows":[["인사·전직·대기발령","인사명령은 원칙적으로 사용자의 고유권한이고 전직의 정당성은 업무상 필요와 생활상 불이익을 비교하여 판단한다 · 근로자 측과 성실한 협의를 거쳤는지는 판단 요소의 하나다 · 인사처분에 노조 사전 동의를 얻도록 한 단체협약 조항도 유효하며 대기발령은 사유가 정당해도 기간이 합리적 범위 안이어야 한다"],["경영상 해고 실체 요건","긴박한 경영상 필요는 기업 전체의 경영사정을 놓고 해고 당시를 기준으로 판단하고, 장래 위기에 대비한 객관적으로 합리적인 감원도 포함된다 · 경영 악화를 막기 위한 사업의 양도·인수·합병은 긴박한 경영상 필요로 본다 · 해고 회피 노력, 합리적이고 공정한 대상자 선정 기준이 함께 필요하며 요건 충족 여부는 개별 사정을 종합하여 판단한다"],["경영상 해고 절차·사후 조치","해고 50일 전까지 과반수 노조(없으면 근로자 과반수 대표)에게 통보하고 성실하게 협의한다 · 과반수 노조와 협의했으면 해고 대상 직원들만의 대표와 따로 협의하지 않아도 되고, 형식상 자격이 부족해도 실질적으로 근로자 의사를 반영하는 대표와 협의했으면 절차 요건을 충족한다 · 일정 규모 이상 해고는 고용노동부장관에게 신고하고, 3년 이내 같은 업무에 채용할 때 해고자를 우선 재고용하며 생계안정·재취업 지원은 정부가 우선 조치한다"]]},{"t":"table","title":"영업양도와 갱신 기대권","head":["항목","내용"],"rows":[["영업양도와 근로관계","영업양도는 조직화된 업체를 동일성을 유지한 채 일체로 이전하는 것이고, 일부 재산을 남겨도 종래 조직이 유지되면 영업양도다 · 근로관계는 원칙적으로 포괄 승계되며 일부 근로자를 빼는 특약은 해고이므로 정당한 이유가 있어야 한다 · 승계를 거부한 근로자는 양도 기업에 남고, 승계 후 퇴직금 규정이 불리하면 종전 규정이 적용된다"],["갱신·재고용 기대권","기간제 근로계약에서 갱신에 대한 정당한 기대권이 인정되면 합리적 이유 없는 갱신 거절은 효력이 없다 · 정년퇴직자에게 기간제 재고용 기대권이 인정되는 경우도 같다"]]}],"6":[{"t":"table","title":"해고예고","head":["항목","내용"],"rows":[["해고예고","근로자를 해고하려면 적어도 30일 전에 예고하고, 예고하지 않으면 30일분 이상의 통상임금을 지급한다"],["예고하지 않아도 되는 경우","계속 근로한 기간이 3개월 미만인 경우, 천재·사변 등 부득이한 사유로 사업 계속이 불가능한 경우, 근로자가 고의로 사업에 막대한 지장이나 재산상 손해를 끼친 경우로서 고용노동부령이 정하는 경우"]]},{"t":"flow","title":"부당해고 구제 절차","steps":["해고된 근로자가 해고 등이 있었던 날부터 3개월 이내에 노동위원회에 구제신청 · 노동조합은 신청인이 될 수 없다","노동위원회가 지체 없이 조사하고 관계 당사자를 심문","부당해고가 성립하면 구제명령, 성립하지 않으면 기각결정 · 사용자와 근로자에게 각각 서면으로 통지","지방노동위원회 결정에 불복하면 통지받은 날부터 10일 이내에 중앙노동위원회에 재심 신청","중앙노동위원회 재심판정서를 송달받은 날부터 15일 이내에 행정소송"]},{"t":"table","title":"구제명령과 금전보상","head":["항목","내용"],"rows":[["구제명령 이행기한","명령한 날부터 30일 이내로 정한다(60일 X)"],["금전보상","근로자가 원직복직을 원하지 않으면 노동위원회는 원직복직 대신 해고기간 임금 상당액 이상의 금품 지급을 명할 수 있다 · 기준은 근로자의 의사이고 ‘사용자가 원하지 않으면’으로 바꾼 선지는 틀렸다 · 근로계약기간 만료나 정년으로 원직복직이 불가능해도 금품 지급을 명할 수 있다(2021 개정)"],["재심·행정소송 기한","기출은 15일을 20일, 30일로 바꿔 냈다"],["효력 부정지","구제명령, 기각결정, 재심판정은 재심 신청이나 행정소송 제기로 효력이 정지되지 않는다"],["소송상 주장","중앙노동위원회 판정 취소소송에서는 기초 사실이 같으면 노동위원회 단계에서 주장하지 않은 사유도 주장할 수 있다"]]},{"t":"table","title":"이행강제금","head":["항목","내용"],"rows":[["부과","구제명령을 이행기한까지 이행하지 않은 사용자에게 3천만원 이하의 이행강제금을 부과한다 · 부과 30일 전까지 문서로 미리 알리고, 부과할 때 액수·사유·납부기한 등을 문서로 통지하며 납부기한은 통지받은 날부터 15일 이내로 정한다 · 최초 구제명령일을 기준으로 매년 2회 범위에서 반복 부과할 수 있고 2년을 넘지 못한다"],["중지·반환·징수","구제명령을 이행하면 새로운 이행강제금은 부과하지 않지만 이미 부과된 것은 징수한다 · 법원 확정판결로 구제명령이 취소되면 부과·징수를 즉시 중지하고 이미 징수한 금액은 반환한다 · 천재·사변 등 부득이한 사유로 이행이 어려우면 직권으로 그 사유가 없어진 뒤에 부과할 수 있고, 납부하지 않으면 독촉 후 국세 체납처분의 예에 따라 징수한다"]]}],"7":[{"t":"table","title":"취업규칙","head":["항목","내용"],"rows":[["작성·신고·의견 청취","상시 10명 이상의 근로자를 사용하면 취업규칙을 작성하여 고용노동부장관에게 신고한다 · 작성·변경 시 과반수 노동조합이 있으면 그 노조의, 없으면 근로자 과반수의 의견을 듣는다 · 근로조건·근로형태·직종 등의 특수성에 따라 일부 근로자에게 적용되는 별도 취업규칙을 만들 수 있다"],["불이익 변경의 동의","취업규칙을 근로자에게 불리하게 바꾸려면 과반수 노조, 없으면 근로자 과반수(회의 방식에 의한 집단적 동의)의 동의를 받는다 · 일부 집단에만 불리해도 다른 집단에 적용이 예상되면 그 집단까지 포함한 전체가 동의 주체다 · 노조가 불리하게 바뀐 취업규칙을 따르기로 단체협약을 맺으면 기존 근로자에게도 적용된다"],["동의 없는 불이익 변경","대법원 전원합의체는 집단적 동의가 없으면 사회통념상 합리성만으로 불리한 변경의 유효성을 인정할 수 없다고 했다 · 다만 노조나 근로자가 동의권을 남용한 경우에는 동의 없이도 유효할 수 있고, 남용 여부는 법원이 직권으로 판단할 수 있다 · 동의 없이 바뀐 취업규칙도 변경 후 신규 입사자에게는 적용되고 현행 법규적 효력을 갖는 취업규칙은 변경된 것이다"],["효력·해석","취업규칙에서 정한 기준에 미달하는 근로계약 부분은 무효이고 무효인 부분은 취업규칙 기준에 따른다 · 작성·변경 권한은 원칙적으로 사용자에게 있고 해석은 문언의 객관적 의미에 따른다 · 근로관계 종료 후의 권리·의무도 근로자의 대우에 관한 사항이면 근로조건에 해당한다"]]},{"t":"table","title":"직장 내 괴롭힘","head":["항목","내용"],"rows":[["개념·신고","사용자 또는 근로자가 직장 내 지위나 관계의 우위를 이용하여 업무상 적정범위를 넘어 다른 근로자에게 신체적·정신적 고통을 주거나 근무환경을 악화시키는 행위다 · 피해자는 ‘다른 근로자’이고 사용자는 피해자로 규정되어 있지 않다 · 누구든지 괴롭힘을 알게 되면 사용자에게 신고할 수 있으며 피해자 동의는 요건이 아니고 신고 의무도 아니다"],["조사·조치","사용자는 신고를 받거나 사실을 인지하면 지체 없이 객관적으로 조사하고, 조사 기간에는 필요하면 피해근로자 의사에 반하지 않게 근무장소 변경·유급휴가 등을 한다 · 사실이 확인되면 피해근로자가 요청할 때 근무장소 변경 등을 하고, 행위자에게는 피해근로자의 의견을 들어 지체 없이 징계 등을 한다 · 신고자와 피해자에게 불리한 처우를 하면 안 되고 조사자는 비밀을 지키되 사용자 보고는 할 수 있다"]]},{"t":"table","title":"기숙사와 근로감독관","head":["항목","내용"],"rows":[["기숙사","사용자는 기숙사 생활의 자치에 필요한 임원 선거에 간섭하지 못한다 · 기숙사규칙 작성·변경에는 기숙 근로자 과반수를 대표하는 자의 동의를 받는다(과반수의 동의 X) · 침실 넓이는 1인당 2.5제곱미터 이상이고, 소음·진동이 심한 장소에는 설치하지 못한다"],["근로감독관","고용노동부와 소속 기관에 두며 사업장·기숙사를 현장조사하고 장부·서류 제출을 요구하며 사용자와 근로자를 심문할 수 있다 · 의사인 근로감독관이나 위촉받은 의사는 취업 금지 질병 의심자를 검진한다 · 그만둔 뒤에도 직무상 비밀을 지켜야 하고, 근로기준법 위반죄에 관하여 사법경찰관 직무를 수행한다"],["벌칙·고발","근기법에 따른 현장조사·서류 제출·심문 등의 수사는 검사와 근로감독관이 전담하되 근로감독관 직무에 관한 범죄 수사는 예외다 · 근로감독관이 위반 사실을 고의로 묵과하면 3년 이하 징역 또는 5년 이하 자격정지이고, 사용자나 그 배우자·4촌 이내 혈족·인척인 근로자가 직장 내 괴롭힘을 하면 1천만원 이하 과태료다 · 확정된 구제명령 불이행은 1년 이하 징역 또는 1천만원 이하 벌금이고 노동위원회의 고발이 있어야 공소를 제기하며 검사는 노동위원회에 고발을 요청할 수 있다(근로감독관 X, ‘하여야’ X)"]]}],"8":[{"t":"table","title":"연소자 사용","head":["항목","내용"],"rows":[["취직인허증","15세 미만인 사람(중학교 재학 중인 18세 미만 포함)은 고용노동부장관의 취직인허증이 있어야 사용할 수 있고, 13세 미만은 예술공연 참가의 경우에만 받을 수 있다 · 신청은 학교장(의무교육 대상자·재학 중인 자) 및 친권자·후견인의 서명을 받아 사용자가 될 자와 연명으로 한다 · 임산부 사용 금지 직종에는 발급하지 않으며 분실하면 사용자가 재교부를 신청하고 본인 동의는 요건이 아니다"],["연소자 비치 서류","18세 미만인 사람을 사용하면 연령을 증명하는 가족관계기록사항 증명서와 친권자 또는 후견인의 동의서를 사업장에 갖추어 둔다 · 두 서류를 모두 두어야 하며 ‘또는’으로 바꾼 선지가 나왔다 · 취직인허증을 갖추어 두면 두 서류를 갖춘 것으로 본다"],["미성년자의 권리","미성년자는 독자적으로 임금을 청구할 수 있고 임금 청구 소송도 독자적으로 할 수 있다 · 근로계약은 친권자·후견인이 대리하지 못하고, 불리한 계약은 친권자·후견인·고용노동부장관이 해지할 수 있다 · 18세 미만인 사람과 계약할 때 근로조건(취업 장소·업무 포함)은 전자문서를 포함한 서면으로 명시·교부한다"],["연소자 근로시간","15세 이상 18세 미만인 사람의 근로시간은 1일 7시간, 1주 35시간을 넘지 못한다 · 당사자 합의로 1일 1시간, 1주 5시간을 한도로 연장할 수 있다"]]},{"t":"table","title":"야간·휴일·시간외 근로","head":["대상","요건"],"rows":[["18세 이상 여성","본인 동의만 있으면 야간·휴일근로를 시킬 수 있다"],["18세 미만자","본인 동의와 고용노동부장관의 인가를 받아야 야간·휴일근로가 가능하다"],["산후 1년 미만 여성","본인 동의와 고용노동부장관의 인가를 받아야 야간·휴일근로가 가능하다 · 단체협약이 있어도 1일 2시간, 1주 6시간, 1년 150시간을 넘는 시간외근로를 시키지 못한다"],["임신 중 여성","명시적 청구가 있고 고용노동부장관의 인가를 받아야 야간·휴일근로가 가능하다 · 시간외근로를 시키지 못하고, 요구하면 쉬운 근로로 전환한다"],["인가 절차","인가를 받기 전에 근로자대표와 성실하게 협의해야 하며 협의가 인가를 대신하지 못한다"]]},{"t":"table","title":"모성보호","head":["항목","내용"],"rows":[["출산전후휴가","출산 전과 후를 통하여 90일(한 번에 둘 이상 임신하면 120일)을 주고 출산 후에 45일(다태아 60일) 이상이 되게 한다 · 유산 경험이 있거나 만 40세 이상이거나 유산·사산 위험이 있다는 진단서를 내면 출산 전 어느 때라도 나누어 쓸 수 있다"],["모성보호 기타","임신 중인 여성이 1일 소정근로시간을 유지하며 업무 시작·종료 시각 변경을 신청하면 허용한다(산후 1년 X) · 임산부 정기건강진단 시간을 청구하면 허용하고, 생후 1년 미만 유아를 가진 여성이 청구하면 1일 2회 각 30분 이상의 유급 수유시간을 준다 · 여성이 청구하면 월 1일의 생리휴가를 주며 위반하면 500만원 이하 벌금이다"],["사용 금지 업무","임산부는 도덕상 또는 보건상 유해·위험한 사업에 사용하지 못하고, 18세 미만인 사람도 같다(정신병원 업무 등) · 여성과 18세 미만인 사람은 갱내에서 근로시키지 못하지만 보건·의료, 보도·취재 등 일시적으로 필요한 업무는 예외다"]]}],"9":[{"t":"table","title":"최저임금의 적용과 효력","head":["항목","내용"],"rows":[["적용 범위","근로자를 사용하는 모든 사업에 적용한다 · 동거하는 친족만 사용하는 사업과 가사사용인, 선원법이 적용되는 선원과 선박 소유자에게는 적용하지 않는다"],["결정 기준·단위","최저임금은 근로자의 생계비, 유사 근로자의 임금, 노동생산성 및 소득분배율 등을 고려하여 정하고 사업의 종류별로 구분할 수 있다 · 단위는 시간·일·주·월이고 ‘연’ 단위는 없다 · 일·주·월 단위로 정하면 시간급으로도 표시한다"],["적용 제외·감액","정신 또는 신체 장애로 근로능력이 현저히 낮은 사람은 사용자가 고용노동부장관의 인가를 받아야 적용에서 뺄 수 있다 · 1년 이상 계약한 수습 근로자는 수습 3개월 이내에 감액할 수 있지만 1년 미만 계약자에게 낮은 최저임금을 정할 수는 없다"],["최저임금의 효력","최저임금에 못 미치는 임금을 정한 부분은 무효이고 최저임금액과 같은 임금을 정한 것으로 본다 · 사용자는 최저임금을 이유로 종전 임금수준을 낮추지 못한다 · 도급인의 책임 있는 사유로 수급인이 최저임금 미만을 지급하면 도급인이 수급인과 연대하여 책임진다"],["산입 범위·도급제","연장·휴일·야간근로 임금과 가산임금은 최저임금에 산입하지 않는다 · 생산고에 따른 임금이나 도급제 임금은 산정기간의 임금 총액을 그 기간의 총근로시간 수로 나누어 시간급을 구한다"]]},{"t":"flow","title":"최저임금 결정 절차","steps":["고용노동부장관이 매년 3월 31일까지 최저임금위원회에 심의 요청","위원회가 요청받은 날부터 90일 이내에 의결안 제출 · 장관이 결정이 어렵다고 보면 20일 이내에 이유를 밝혀 10일 이상의 기간을 정해 재심의 요청","장관이 매년 8월 5일까지 최저임금을 결정하고 지체 없이 고시","근로자 대표와 사용자 대표가 고시일부터 10일 이내에 이의 제기(30일 X)","사용자가 최저임금액, 산입하지 않는 임금, 적용 제외 근로자 범위, 효력발생일을 효력발생일 전날까지 근로자에게 알림"]},{"t":"table","title":"최저임금위원회","head":["항목","내용"],"rows":[["구성","위원회는 고용노동부에 두고 근로자위원·사용자위원·공익위원 각 9명으로 구성한다 · 상임위원은 공익위원이 되고, 위원장과 부위원장은 공익위원 중에서 위원회가 선출한다 · 위원 임기는 3년이고 연임할 수 있으며 임기가 끝나도 후임자가 정해질 때까지 직무를 수행한다"],["운영","회의는 재적위원 과반수 출석과 출석위원 과반수 찬성으로 의결한다 · 전문위원회는 근로자·사용자·공익위원 각 5명 이내 같은 수로 구성하고, 관계 행정기관 공무원 중 3명 이내의 특별위원을 둘 수 있다 · 고용노동부장관은 근로자의 생계비와 임금실태를 매년 조사한다(격년 X)"]]}],"10":[{"t":"table","title":"퇴직급여제도","head":["항목","내용"],"rows":[["설정 대상","사용자는 퇴직급여제도를 설정해야 하지만 계속근로기간이 1년 미만인 근로자와 4주 평균 1주 소정근로시간이 15시간 미만인 근로자는 제외된다 · 하나의 사업에서 급여와 부담금 산정방법을 차등하면 안 된다 · 퇴직급여제도는 확정급여형·확정기여형 퇴직연금제도, 중소기업퇴직연금기금제도, 퇴직금제도를 말한다(중소기업퇴직연금기금제도는 2021 개정으로 추가)"],["설정·변경 절차","퇴직급여제도를 설정하거나 다른 종류로 변경하려면 과반수 노조가 있으면 그 노조, 없으면 근로자 과반수의 동의를 받는다 · ‘사전협의’로 바꾼 선지가 출제됐다"],["퇴직금","퇴직금은 계속근로기간 1년에 30일분 이상의 평균임금이다(통상임금 X) · 퇴직 후 14일 이내에 지급하되 특별한 사정이 있으면 당사자 합의로 기일을 연장할 수 있다 · 퇴직금을 받을 권리는 3년간 행사하지 않으면 시효로 소멸한다"],["중간정산","무주택자가 본인 명의로 주택을 사거나 전세금을 부담하는 경우, 본인·가족의 6개월 이상 요양, 파산·회생 등 법정 사유가 있으면 근로자 요구로 미리 정산할 수 있다 · 사유 없이 요구한다고 정산할 수 있는 것은 아니다"]]},{"t":"vs","title":"확정급여형과 확정기여형","cols":[{"name":"확정급여형(DB)","items":["근로자가 받을 급여 수준이 미리 정해진 제도다","사용자는 근로자대표의 동의를 얻거나 의견을 들어 규약을 작성하고 고용노동부장관에게 신고하며 설정 전 근로기간도 가입기간에 넣을 수 있다","연금은 55세 이상이고 가입기간 10년 이상인 가입자에게 지급기간 5년 이상으로 준다","일시금은 연금 요건을 못 갖추거나 일시금을 원하는 가입자에게 준다"]},{"name":"확정기여형(DC)","items":["확정기여형을 설정한 사용자는 매년 1회 이상 가입자의 연간 임금총액의 12분의 1 이상을 현금으로 가입자 계정에 납입한다","상시 10명 미만 사업에서 근로자 동의나 요구로 개인형퇴직연금제도를 설정하면 퇴직급여제도를 설정한 것으로 본다"]}]},{"t":"table","title":"중소기업퇴직연금기금과 퇴직연금 운영","head":["항목","내용"],"rows":[["중소기업퇴직연금기금","중소기업퇴직연금기금제도는 근로복지공단이 운영한다(고용노동부 X) · 운영위원회는 위원장 포함 10명 이상 15명 이내로 하고 근로자 대표 위원과 사용자 대표 위원 수를 같게 한다 · 사용자는 매년 1회 이상 연간 임금총액의 12분의 1 이상을 납입하고, 급여를 받을 권리는 양도·압류할 수 없다"],["퇴직연금 운영","퇴직연금사업자는 매년 1회 이상 적립금액과 운용수익률 등을 가입자에게 알린다(매분기 X) · 적립금운용위원회 구성 의무는 상시 300명 이상 사업에 있다(100명 X)"]]}],"11":[{"t":"table","title":"정의와 차별 금지","head":["항목","내용"],"rows":[["정의·적용 범위","이 법의 근로자는 사업주에게 고용된 사람과 취업할 의사를 가진 사람이다 · 적극적 고용개선조치는 현존하는 남녀 간 고용차별을 없애거나 고용평등을 촉진하려고 잠정적으로 특정 성을 우대하는 조치다 · 동거 친족만으로 이루어진 사업과 가사사용인에게는 법 전부를 적용하지 않고, 상시 4명 이하 사업은 일부 규정만 빠진다"],["모집·채용·임금 차별 금지","모집·채용에서 남녀를 차별하지 못하고 직무에 필요 없는 용모·키·체중 등 신체 조건이나 미혼 조건을 요구하지 못한다 · 동일가치노동의 기준을 정할 때 노사협의회 근로자위원의 의견을 듣고, 임금차별 목적으로 세운 별개 사업은 동일 사업으로 본다 · 직무 성격상 특정 성이 불가피하게 요구되면 차별이 아니다"],["성희롱·입증책임","누구든지 직장 내 성희롱 발생 사실을 사업주에게 신고할 수 있다 · 이 법 관련 분쟁의 입증책임은 사업주가 부담한다(각자 부담 X) · 사업주는 노사협의회가 추천하는 사람을 명예고용평등감독관으로 위촉할 수 있고 의무는 아니며 고용노동부장관은 기본계획을 5년마다 세운다"],["노동위원회 차별 시정","차별적 처우를 받거나 성희롱 신고·피해를 이유로 불리한 처우(감봉 등)를 받거나 사업주가 피해자 보호조치를 하지 않으면 노동위원회에 시정을 신청할 수 있다 · 성희롱 행위자를 징계하지 않은 것은 신청 사유가 아니다 · 노동위원회는 차별 등이 인정되면 시정명령을 하고 고용노동부장관은 확정된 명령의 이행상황 제출을 요구할 수 있다"]]},{"t":"table","title":"출산·육아 지원","head":["항목","내용"],"rows":[["배우자 출산·난임 휴가","배우자 출산휴가는 20일 유급이고 출산일부터 120일 안에 청구하며 3회까지 나누어 쓸 수 있다(2025 개정) · 난임치료휴가는 연간 6일이고 최초 2일이 유급이다(2025 개정) · 2019년 기출의 ‘5일 범위 3일 이상’과 2024년 기출의 ‘3일·최초 1일’은 개정 전 내용이다"],["육아휴직 요건","만 8세 이하 또는 초등학교 2학년 이하 자녀를 위해 1년 이내로 쓰고, 부모가 각각 3개월 이상 쓰면 1년 6개월까지 늘어난다(2025 개정) · 휴직개시예정일 전날까지 계속근로 6개월 미만인 근로자는 사업주가 허용하지 않을 수 있다"],["육아휴직 절차","임신 중 유산·사산 위험이 있으면 휴직개시예정일 7일 전까지 신청할 수 있다 · 신청은 휴직개시예정일 7일 전까지 철회할 수 있고 종료예정일 연기는 한 번만 가능하다 · 영유아 사망 등의 통지를 받으면 사업주는 통지받은 날부터 30일 이내로 근무개시일을 지정해 알린다"],["육아기 근로시간 단축","단축 후 근로시간은 주 15시간 이상 35시간 이하다(기출 X 선지는 ‘10시간 이상 30시간’) · 대상 자녀는 만 12세 이하 또는 초등학교 6학년 이하로 넓어졌다(2025 개정) · 허용하지 않으면 사유를 서면으로 알리고, 나누어 쓸 수 있으며 끝나면 같은 업무나 같은 수준 임금의 직무로 복귀시키고 단축 기간은 평균임금 산정기간에서 뺀다"],["가족돌봄·은퇴준비 단축","가족돌봄휴직은 연간 최장 90일이다(60일 X) · 가족돌봄 등 근로시간 단축은 주 15시간 이상 30시간 이하다 · 55세 이상 근로자의 은퇴 준비 단축 중 근로자가 명시적으로 청구하면 주 12시간 이내 연장근로를 시킬 수 있다"]]}],"12":[{"t":"table","title":"기간제·단시간근로자","head":["항목","내용"],"rows":[["기간제 2년 한도·예외","기간제근로자는 2년을 넘어 사용할 수 없고, 넘으면 기간의 정함이 없는 근로자로 본다 · 사업 완료나 특정 업무 완성에 필요한 기간을 정한 경우, 휴직·파견 등 결원을 복귀 때까지 대신하는 경우, 학업·직업훈련, 55세 이상 고령자, 전문 지식·기술 활용 등은 2년을 넘어 쓸 수 있다 · 상시 5명 이상 사업에 적용하고 동거 친족만 쓰는 사업은 제외한다"],["서면 명시·단시간 초과근로","기간제·단시간근로자와 계약할 때 근로계약기간, 근로시간·휴게, 임금, 휴일·휴가, 취업 장소와 업무를 서면으로 명시하고 ‘근로일 및 근로일별 근로시간’은 단시간근로자에게만 명시한다 · 단시간근로자에게 소정근로시간을 넘겨 일을 시키려면 동의가 필요하고 그 경우에도 1주 12시간을 넘지 못하며 초과근로에는 통상임금의 100분의 50 이상을 가산한다"],["통상근로 전환 노력","사용자는 통상근로자를 채용하려면 같은 업무의 단시간근로자를 우선 고용하도록 노력한다(‘우선 고용하여야’ X) · 가사·학업 등을 이유로 근로자가 단시간근로를 신청하면 단시간근로자로 전환하도록 노력한다"]]},{"t":"flow","title":"차별 시정 절차","steps":["기간제·단시간근로자가 차별적 처우가 있은 날(계속되는 차별은 종료일)부터 6개월 이내에 노동위원회에 시정 신청(3개월 X) · 차별 내용을 구체적으로 적는다","노동위원회가 심문 중 쌍방 또는 일방의 신청이나 직권으로 조정 절차 시작 · 조정 신청은 시정신청일부터 14일 이내가 원칙이지만 노동위원회 승낙이 있으면 그 뒤에도 가능","조정안은 특별한 사유가 없으면 60일 이내에 제시 · 조정에는 적절한 배상이 포함될 수 있고, 중재결정서에는 관여한 위원 전원이 서명·날인한다(관계당사자 서명 X)","차별에 명백한 고의가 있거나 차별이 반복되면 손해액의 3배를 넘지 않는 범위에서 배상을 명할 수 있다","확정된 시정명령을 사용자가 이행하지 않으면 근로자는 고용노동부장관에게 신고할 수 있고, 장관은 직접 사용자에게 시정을 요구할 수도 있다"]},{"t":"def","term":"차별적 처우","text":"기간제근로자만 가질 수 있는 속성을 원인으로 한 불리한 처우도 기간제임을 이유로 한 차별이고, 노동위원회는 신청인이 주장한 비교대상자와 동일성이 인정되는 범위에서 적합한 비교대상자를 고를 수 있다"},{"t":"table","title":"파견근로자 보호","head":["항목","내용"],"rows":[["파견사업 허가·폐지","근로자파견사업은 고용노동부장관의 허가를 받아야 한다 · 허가 유효기간은 3년이고 갱신허가 유효기간은 종전 허가의 유효기간이 끝나는 날의 다음 날부터 3년이다(2년 X) · 폐지는 허가가 아니라 신고 사항이고 신고일부터 허가가 효력을 잃는다"],["파견 금지·직접고용","파견사업주는 쟁의행위 중인 사업장에 중단된 업무 수행을 위해 파견하지 못하며 근로자대표 동의가 있어도 같다 · 대상 업무가 아닌 곳에 쓰거나 2년을 넘겨 쓰면 사용사업주에게 직접고용 의무가 생기고, 직접고용한 것으로 간주되는 것은 아니다 · 고령자(55세 이상)는 2년을 넘어 파견할 수 있고, 사용사업주는 직접 고용하려는 업무의 파견근로자를 우선 고용하도록 노력한다"],["파견사업주·사용사업주의 책임","유급휴일과 연차휴가의 임금은 파견사업주가 지급하고, 1주 1회 이상 유급휴일 보장과 수유시간 부여는 사용사업주가 한다 · 파견사업주는 위약금 예정 계약, 고용관계 종료 후 사용사업주 고용을 막는 계약, 명의 대여를 하지 못하고, 파견근로자가 아닌 자기 근로자를 파견하려면 서면으로 알리고 동의를 받는다 · 파견 대가 내역은 파견사업주에게 요구하며 사용사업관리책임자는 사용사업주가 선임한다"]]}],"13":[{"t":"table","title":"산업안전보건법의 적용과 정의","head":["항목","내용"],"rows":[["적용 범위·중대재해","산업안전보건법은 국가·지방자치단체·공기업에도 적용된다 · 중대재해는 사망자 1명 이상, 3개월 이상 요양이 필요한 부상자가 동시에 2명 이상, 부상자 또는 직업성 질병자가 동시에 10명 이상 발생한 재해다 · 직업성 질병자 2명은 중대재해가 아니다"],["주요 정의","산업재해는 노무를 제공하는 사람이 업무 관련 설비·원재료·가스·분진 등이나 작업으로 사망·부상·질병에 걸리는 것이다 · 위험성평가는 유해·위험 요인을 찾아 부상·질병으로 이어질 위험성의 크기가 허용 가능한 범위인지 평가하는 것이고, 작업환경측정은 측정계획을 세워 시료를 채취·분석·평가하는 것이다 · 도급인에서 건설공사발주자는 빠지고, 관계수급인은 여러 단계 도급에서 각 단계별로 도급받은 사업주 전부다"]]},{"t":"table","title":"규정과 평가·측정","head":["항목","내용"],"rows":[["안전보건관리규정","일정 규모 이상(보험업 등은 상시 300명 이상) 사업주는 안전보건관리규정을 작성하여 게시하고 근로자에게 알린다 · 산업안전보건위원회가 없으면 근로자대표의 동의를 받아 작성하고, 사고 조사와 대책 수립에 관한 사항이 들어가야 한다 · 안전보건관리규정은 단체협약이나 취업규칙에 반할 수 없고, 반하는 부분은 단체협약·취업규칙을 따른다(방향을 뒤집은 선지가 나왔다)"],["위험성평가","사업주는 위험성평가를 할 때 해당 작업장 근로자를 참여시킨다 · 결과와 조치사항은 위험성 결정 내용을 포함하여 기록하고 3년간 보존한다"],["근로자대표 참석·작업환경측정","근로자대표가 요구하면 건강진단과 작업환경측정에 근로자대표를 참석시킨다 · 도급인 사업장에서 관계수급인 근로자가 작업하면 도급인이 작업환경측정을 하게 한다 · 측정은 작업환경측정기관에 위탁할 수 있고 시료 분석만 위탁할 수도 있다"]]},{"t":"table","title":"근로시간·도급·건강관리","head":["항목","내용"],"rows":[["근로시간 제한·휴게시설","잠함·잠수 등 고기압 작업 근로자에게는 1일 6시간, 1주 34시간을 넘는 근로를 시키지 못한다(5시간 X) · 사업주는 관계수급인 근로자를 포함한 근로자가 쓸 휴게시설을 갖춘다"],["도급·작업중지","도금·수은·납·카드뮴 등 일부 유해 작업은 도급이 금지되거나 고용노동부장관 승인을 받아야 하며 모든 유해·위험 작업이 허가 대상인 것은 아니다 · 사업주는 산재 예방 능력을 갖춘 사업주에게 도급한다 · 산업재해 발생의 급박한 위험이 있으면 즉시 작업을 중지시키고 근로자를 대피시킨다"],["고객응대·건강관리","고객의 폭언 등으로 고객응대근로자에게 건강장해가 생기거나 생길 우려가 크면 업무의 일시 중단·전환 등을 한다 · 임시건강진단은 고용노동부장관이 명하고 산업보건의가 명하는 것이 아니다 · 건강관리카드 소지자는 산재 요양급여 신청 때 카드로 의학적 소견서 제출을 대신할 수 있다"],["지도사","지도사는 고용노동부장관에게 등록하고 직무 서류에 기명·날인하거나 서명하며 고의·과실로 의뢰인에게 손해를 입히면 배상한다 · 업무 관련 서류를 거짓으로 작성하거나 업무정지 기간 중에 업무를 하면 등록을 취소한다"]]}],"14":[{"t":"table","title":"임금채권보장법","head":["항목","내용"],"rows":[["적용·용어","이 법은 산재보험법이 적용되는 사업에 적용하고 국가와 지방자치단체가 직접 하는 사업에는 적용하지 않는다 · 이 법의 사업주는 근로자를 사용하여 사업을 하는 자이며 근기법상 사용자와 범위가 다르다"],["대지급금 사유·청구","퇴직 근로자는 파산선고, 회생절차개시결정, 도산등사실인정이 있으면 도산대지급금을 받는다(회생절차개시 ‘신청’만으로는 안 된다) · 도산대지급금은 파산선고등이나 도산등사실인정이 있은 날부터 2년 이내에 고용노동부장관에게 청구한다(3년·근로복지공단 X) · 재직 근로자 대지급금은 하나의 사업에서 1회만 지급한다"],["대지급금 범위·보호","최종 3개월분 임금과 휴업수당, 최종 3년분 퇴직급여 등이 대지급금 범위다 · 미성년자도 독자적으로 청구할 수 있고, 대지급금수급계좌의 예금 채권은 압류할 수 없다 · 지급한 장관은 그 금액 한도에서 근로자의 권리를 대위하고 근기법상 우선변제권도 대위된 권리에 존속하며 대지급금을 반환받을 권리는 3년간 행사하지 않으면 시효로 소멸한다"],["부담금·기금","사업주 부담금은 보수총액에 1천분의 2 범위에서 정한 비율을 곱한 금액이다(1천분의 3 X) · 퇴직금을 미리 정산한 사업주와 외국인근로자 출국만기보험에 가입한 사업주는 부담금을 경감할 수 있다 · 임금채권보장기금은 고용노동부장관이 설치·관리·운용하고 심의위원회는 고용노동부에 둔다(근로복지공단 X)"]]},{"t":"table","title":"근로복지","head":["항목","내용"],"rows":[["사내근로복지기금","사내근로복지기금은 법인이고 자금을 차입할 수 없다 · 설립인가증을 받은 날부터 3주 이내에 설립등기를 하고, 기금협의회가 이사와 감사의 선임·해임을 협의·결정한다 · 사용자는 기금 설립을 이유로 근로조건을 낮추거나 기존 근로복지 운영을 중단·감축하지 못한다"],["근로복지시설·우리사주","근로복지시설 운영자는 소득수준, 가족관계 등을 고려하여 이용자를 제한하거나 이용료를 차등할 수 있다(세 차례 X 선지로 출제) · 선택적 복지제도도 직급·근속연수·부양가족에 따라 수혜 수준을 달리할 수 있다 · 우리사주는 조합원 의사와 무관하게 할당할 수 없고, 조합 규약 제정·변경은 조합원총회 의결을 거치며 지배관계회사에서 취득자금을 빌릴 수 있다"]]},{"t":"table","title":"직업소개와 근로자공급","head":["항목","내용"],"rows":[["직업소개사업","국내 무료직업소개는 시장·군수·구청장에게 신고, 국외 무료직업소개는 고용노동부장관에게 신고한다 · 국내 유료직업소개는 시장·군수·구청장에게 등록, 국외 유료직업소개는 장관에게 등록한다 · 유료소개사업자는 구인자에게서 선급금을 받지 못하고 등록증을 대여하지 못하며 결혼중개업·숙박업 등을 겸업하지 못한다"],["근로자공급·직업안정","근로자공급사업은 고용노동부장관의 허가를 받아야 하고 국내 근로자공급사업은 노동조합이 허가를 받을 수 있으며 파견사업은 근로자공급사업에서 빠진다 · 직업적성검사는 구직자 동의가 있어야 하고, 18세 미만 구직자를 소개할 때는 친권자나 후견인의 취업동의서를 받는다 · 근로복지공단(업무상 재해자 대상), 한국장애인고용공단(장애인 대상) 등은 신고 없이 무료직업소개를 할 수 있다"],["외국인근로자 고용","선원법 적용 선원에게는 이 법을 적용하지 않는다 · 고용허가서 발급일부터 3개월 이내에 표준근로계약서로 계약하고 근로계약 효력은 입국한 날부터 생기며, 취업활동 기간은 입국일부터 3년이고 입국 후 15일 이내에 취업교육을 받는다 · 출입국관리법 위반으로 처벌받은 사용자는 3년간 고용을 제한할 수 있고(5년·6년·‘하여야’ X), 고용허가가 취소되면 15일 이내에 근로계약을 끝낸다"]]}]};
