(window.TNQ=window.TNQ||[]).push({"terms":{"직장존속보장청구권":{"d":"국가에 대해 직장을 계속 유지해 달라고 직접 요구할 수 있는 권리로 헌법상 인정되지 않습니다.","r":[]},"시용":{"d":"본채용 전에 일정 기간 근로자를 써 보는 제도로 사용자에게 해약권이 유보되어 있습니다.","r":[]},"평균임금":{"d":"산정 사유가 발생한 날 이전 3개월 동안 지급된 임금 총액을 그 기간의 총일수로 나눈 금액이다.","r":[]},"통상임금":{"d":"근로자에게 정기적이고 일률적으로 소정근로에 대해 지급하기로 정한 시간급, 일급, 주급, 월급 또는 도급 금액이다.","r":[]},"휴업수당":{"d":"사용자의 귀책사유로 휴업하는 경우 근로자에게 지급하는 평균임금의 100분의 70 이상의 수당이다.","r":[]},"탄력적 근로시간제":{"d":"일정한 단위기간을 평균해 주당 근로시간이 법정 한도를 넘지 않으면 특정한 주나 날에 한도를 초과해 근로하게 할 수 있는 제도이다.","r":[]},"영업양도":{"d":"사업의 인적, 물적 조직을 동일성을 유지하며 일체로 이전하는 것으로 근로관계도 원칙적으로 포괄 승계된다.","r":[]},"이행강제금":{"d":"구제명령을 받고도 이행기한까지 이행하지 않는 사용자에게 노동위원회가 부과하는 금전적 제재로, 의무 이행을 간접적으로 강제한다.","r":[]},"취업규칙":{"d":"사용자가 근로조건과 복무규율에 관해 일률적으로 정한 규칙으로 상시 10명 이상 사용하면 작성해 신고해야 한다.","r":[]},"직장 내 괴롭힘":{"d":"직장에서 지위나 관계의 우위를 이용해 업무상 적정범위를 넘어 다른 근로자에게 신체적 정신적 고통을 주거나 근무환경을 악화시키는 행위이다.","r":[]},"취직인허증":{"d":"15세 미만인 자를 근로자로 사용하려 할 때 고용노동부장관이 내주는 증서이다.","r":[]},"출산전후휴가":{"d":"임신 중인 여성에게 출산 전과 후를 통틀어 주는 휴가로 한 번에 둘 이상의 자녀를 임신한 경우 기간이 더 길다.","r":[]},"최저임금":{"d":"법으로 정한 임금의 최저 한도로 이보다 낮게 정한 근로계약 부분은 무효입니다.","r":[]},"퇴직급여제도":{"d":"확정급여형퇴직연금제도, 확정기여형퇴직연금제도 및 퇴직금제도를 통틀어 이르는 말이다.","r":[]},"확정급여형":{"d":"근로자가 받을 퇴직급여 수준이 미리 정해진 퇴직연금제도입니다.","r":["확정기여형"]},"확정기여형":{"d":"사용자가 납입할 부담금 수준이 정해지고 운용 결과에 따라 급여가 달라지는 퇴직연금제도입니다.","r":["확정급여형"]},"배우자 출산휴가":{"d":"근로자가 배우자의 출산을 이유로 청구하는 유급휴가입니다.","r":[]},"육아휴직":{"d":"자녀를 키우기 위해 근로자가 신청하는 휴직이다.","r":[]},"가족돌봄휴직":{"d":"가족을 돌보기 위해 근로자가 신청하는 휴직으로 연간 일정 기간까지 쓸 수 있다.","r":[]},"기간제근로자":{"d":"근로계약기간이 정해져 있는 근로자이다.","r":[]},"단시간근로자":{"d":"1주 소정근로시간이 같은 사업장의 같은 종류 업무에 종사하는 통상근로자보다 짧은 근로자이다.","r":[]},"파견사업주":{"d":"근로자파견사업을 하는 자로 파견근로자를 고용해 사용사업주에게 보낸다.","r":[]},"사용사업주":{"d":"파견사업주와 근로자파견계약을 맺고 파견근로자를 사용하는 사업주이다.","r":[]},"중대재해":{"d":"사망자가 1명 이상 발생하는 등 산업재해 중 피해가 특히 큰 재해이다.","r":[]},"위험성평가":{"d":"유해하거나 위험한 요인을 찾아내 부상과 질병으로 이어질 위험성의 크기가 허용 가능한 범위인지 평가하는 것이다.","r":[]},"작업환경측정":{"d":"작업환경 실태를 파악하기 위해 유해인자에 대한 근로자의 노출 정도를 측정하고 분석하는 일이다.","r":[]},"도산대지급금":{"d":"사업의 도산 사실이 인정된 때 퇴직한 근로자에게 국가가 대신 지급하는 임금등이다.","r":[]},"사내근로복지기금":{"d":"사업주가 출연한 재원으로 근로자의 복지 증진을 위한 사업을 하는 기금이다.","r":[]},"우리사주":{"d":"근로자가 자기 회사의 주식을 취득해 보유하도록 하는 제도이다.","r":[]},"근로자공급사업":{"d":"공급계약에 따라 근로자를 타인에게 공급해 사용하게 하는 사업으로 근로자파견사업은 제외한다.","r":[]},"구제명령":{"d":"노동위원회가 부당해고등이 성립한다고 판정할 때 사용자에게 내리는 명령으로 원직복직과 임금 상당액 지급 등을 포함한다.","r":[]},"기각결정":{"d":"노동위원회가 부당해고등이 성립하지 않는다고 판단해 근로자의 구제신청을 받아들이지 않는 결정이다.","r":[]},"재심판정":{"d":"중앙노동위원회가 지방노동위원회의 구제명령이나 기각결정에 대한 재심신청을 심리해 내리는 판정이다.","r":[]},"부당해고등":{"d":"부당해고, 부당휴직, 정직, 전직, 감봉, 그 밖의 징벌을 통틀어 이르는 말이다.","r":[]},"구제신청":{"d":"부당해고등을 당한 근로자가 노동위원회에 권리 구제를 구하는 신청이다.","r":[]},"국세 체납처분":{"d":"국세를 내지 않은 경우 재산을 압류하고 공매해 징수하는 절차로, 이행강제금 징수에도 준용된다.","r":[]},"해고 예고":{"d":"사용자가 근로자를 해고하려면 적어도 30일 전에 예고하거나 30일분 이상의 통상임금을 지급해야 하는 제도이다.","r":[]},"귀책사유":{"d":"책임을 질 만한 잘못된 행위가 있는 사유이다.","r":[]},"균등한 처우":{"d":"사용자가 성별, 국적, 신앙, 사회적 신분을 이유로 근로조건에서 차별하지 못하게 하는 근로기준법의 기본원칙이다.","r":[]},"사회적 신분":{"d":"사람이 사회에서 장기간 점하는 지위로 선천적 신분뿐 아니라 후천적으로 얻은 지위도 포함하는 말이다.","r":[]},"근로조건의 명시":{"d":"근로계약 체결 때 사용자가 임금, 소정근로시간, 휴일, 연차 유급휴가 등을 근로자에게 밝혀 서면으로 교부하는 의무이다.","r":[]},"단체협약":{"d":"노동조합과 사용자 사이에 근로조건 등에 관해 서면으로 맺은 합의이다.","r":[]},"소정근로시간":{"d":"법정 근로시간의 범위에서 근로자와 사용자가 정한 근로시간이다.","r":[]},"단위기간":{"d":"탄력적 근로시간제나 선택적 근로시간제에서 평균 근로시간을 계산하는 기준이 되는 기간이다.","r":[]},"재량근로":{"d":"업무 수행 방법을 근로자의 재량에 맡길 필요가 있어 서면 합의로 정한 시간을 근로한 것으로 보는 제도이다.","r":[]},"선택적 근로시간제":{"d":"정산기간을 평균해 주당 근로시간이 법정 한도를 넘지 않으면 근로자가 업무의 시작과 종료 시각을 스스로 결정하게 하는 제도이다.","r":[]},"정산기간":{"d":"선택적 근로시간제에서 근로시간을 평균하여 계산하는 기간이다.","r":[]},"근로자대표":{"d":"근로자의 과반수로 조직된 노동조합이 없을 때 근로자 과반수를 대표하는 사람이다.","r":[]},"휴게시간":{"d":"근로시간 도중에 근로자가 근로에서 벗어나 자유롭게 이용할 수 있는 시간이다.","r":[]},"유급휴일":{"d":"근로를 제공하지 않아도 임금을 지급받는 휴일로 1주에 평균 1회 이상 보장해야 한다.","r":[]},"연차 유급휴가":{"d":"일정 기간 출근한 근로자에게 임금을 지급하며 주는 휴가이다.","r":[]},"가산휴가":{"d":"계속 근로 연수가 늘어남에 따라 연차 유급휴가에 더해 주는 휴가이다.","r":[]},"연장근로":{"d":"법정 근로시간을 초과해 하는 근로로 통상임금의 100분의 50 이상을 가산해 지급한다.","r":[]},"휴일근로":{"d":"휴일에 하는 근로로 가산임금 지급 대상이다.","r":[]},"단속적":{"d":"근로시간 중 휴게나 대기 시간이 많은 업무의 성질로, 일정한 요건을 갖추면 근로시간과 휴일 규정의 예외로 다룬다.","r":[]},"징계양정":{"d":"비위행위의 정도에 맞게 징계의 종류와 수위를 정하는 것이다.","r":[]},"징계처분":{"d":"기업 질서를 어긴 근로자에게 사용자가 내리는 제재이다.","r":[]},"시용기간":{"d":"정식 채용 전에 근로자의 업무 적격성을 평가하기 위해 두는 시험 사용 기간이다.","r":[]},"해약권":{"d":"시용기간 중 또는 만료 때 사용자가 본계약 체결을 거부할 수 있도록 유보한 권리이다.","r":[]},"기대권":{"d":"기간을 정한 근로계약에서 갱신될 것이라고 근로자가 합리적으로 기대할 수 있는 권리이다.","r":[]},"갱신":{"d":"기간이 정해진 근로계약을 기간 만료 후 다시 이어 가는 것이다.","r":[]},"정리해고":{"d":"긴박한 경영상의 필요로 사용자가 일정한 요건을 갖추어 하는 해고이다.","r":[]},"긴박한 경영상의 필요":{"d":"정리해고의 첫째 요건으로 기업 전체의 경영사정을 종합해 인원 감축이 불가피한 상황이다.","r":[]},"해고회피노력":{"d":"정리해고에 앞서 사용자가 신규 채용 중단, 배치전환 등으로 해고를 피하려고 하는 노력이다.","r":[]},"해고대상자 선정기준":{"d":"정리해고 때 합리적이고 공정하게 정해야 하는 해고 대상 근로자 선택의 기준이다.","r":[]},"우선 재고용":{"d":"정리해고 후 근로자를 채용할 때 해고된 근로자를 우선적으로 다시 고용하는 의무이다.","r":[]},"대기발령":{"d":"근로자에게 일정 기간 직무를 부여하지 않고 대기하게 하는 인사명령이다.","r":[]},"전직":{"d":"근로자의 직무 내용이나 근무 장소를 바꾸는 인사처분이다.","r":[]},"인사권":{"d":"사용자가 근로자의 채용, 배치, 승진, 징계 등을 결정하는 권한이다.","r":[]},"채용내정":{"d":"정식 입사 전에 채용을 확정했음을 통지한 상태로 해약권이 유보된 근로계약이 성립한 것으로 본다.","r":[]},"사용증명서":{"d":"퇴직한 근로자가 청구하면 사용 기간, 업무 종류, 지위, 임금 등을 사실대로 적어 내주는 증명서이다.","r":[]},"근로자 명부":{"d":"사용자가 각 사업장별로 근로자의 성명, 생년월일 등을 적어 작성하는 장부이다.","r":[]},"임금대장":{"d":"사용자가 임금 계산의 기초가 되는 사항과 임금액 등을 적어 보존해야 하는 장부이다.","r":[]},"임금채권":{"d":"근로자가 사용자에게 임금의 지급을 청구할 수 있는 권리이다.","r":[]},"상계":{"d":"서로 같은 종류의 채권과 채무를 가진 당사자가 대등액만큼 소멸시키는 것으로 임금은 원칙적으로 사용자가 상계하지 못한다.","r":[]},"소멸시효":{"d":"권리를 일정 기간 행사하지 않으면 그 권리가 사라지는 제도이다.","r":[]},"체불사업주":{"d":"임금등을 지급하지 않아 명단 공개나 체불자료 제공의 대상이 되는 사업주이다.","r":[]},"종합신용정보집중기관":{"d":"금융기관 등의 신용정보를 모아 관리하는 기관으로 임금등 체불자료를 제공받아 신용도 판단에 이용할 수 있다.","r":[]},"집단적 동의권":{"d":"취업규칙을 근로자에게 불리하게 바꿀 때 근로자 과반수의 동의를 받아야 하는 권리이다.","r":[]},"불이익변경":{"d":"취업규칙의 변경으로 근로자의 기존 권리나 근로조건이 불리해지는 것이다.","r":[]},"감급":{"d":"징계로 임금에서 일정액을 깎는 제재로 1회 금액과 총액에 한도가 있다.","r":[]},"근로감독관":{"d":"근로기준법 등 노동관계 법령의 시행을 위해 사업장을 감독하고 위반의 죄에 관해 사법경찰관의 직무를 수행하는 공무원이다.","r":[]},"사법경찰관":{"d":"범죄를 수사하는 직무를 수행하는 경찰관과 특별법에 따라 이 권한을 부여받은 공무원이다.","r":[]},"기숙사규칙":{"d":"사용자가 기숙사 생활과 안전, 보건에 관해 근로자 과반수의 동의를 받아 정하는 규칙이다.","r":[]},"미숙아":{"d":"신체의 발육이 미숙한 상태로 출생한 영유아로 출산전후휴가 기간이 달라지는 경우의 대상이다.","r":[]},"친권자":{"d":"미성년 자녀를 보호하고 양육하며 재산을 관리하는 부모이다.","r":[]},"후견인":{"d":"미성년자 등을 보호하고 대리하는 사람으로 친권자가 없을 때 두는 보호자이다.","r":[]},"산업안전보건위원회":{"d":"사업장의 산업재해 예방에 관한 중요 사항을 심의하고 의결하기 위해 근로자와 사용자가 같은 수로 참여하는 위원회이다.","r":[]},"안전보건관리책임자":{"d":"사업장의 산업재해 예방 업무를 총괄하여 관리하는 사람으로 그 사업을 실질적으로 총괄하는 사람이 맡는다.","r":[]},"안전보건관리규정":{"d":"사업주가 안전보건교육, 사고조사와 대책수립 등을 포함해 작성하여 근로자에게 알려야 하는 사업장의 안전과 보건에 관한 규정이다.","r":[]},"관계수급인":{"d":"도급이 여러 단계에 걸쳐 체결된 경우 각 단계에서 도급받은 사업주 전부를 이르는 말이다.","r":[]},"건설공사발주자":{"d":"건설공사를 도급하는 자로서 시공을 주도하여 총괄하고 관리하지 않는 자이다.","r":[]},"보건조치":{"d":"산소결핍, 방사선, 단순반복작업 등으로 인한 건강장해를 예방하기 위해 사업주가 해야 하는 조치이다.","r":[]},"산업보건의":{"d":"사업장의 근로자 건강관리를 위해 두는 의사로 근로자의 건강진단 결과 사후관리 등을 돕는다.","r":[]},"임시건강진단":{"d":"같은 유해인자에 노출되는 근로자에게 유사한 질병의 증상이 발생하는 등의 경우에 실시하는 건강진단이다.","r":[]},"건강관리카드":{"d":"직업성 질병의 위험이 있는 업무에 종사했던 사람에게 발급하는 카드로 건강진단을 무료로 받을 수 있게 한다.","r":[]},"요양급여":{"d":"산업재해보상보험에서 업무상 부상이나 질병으로 치료가 필요한 근로자에게 지급하는 급여이다.","r":[]},"체당금":{"d":"임금채권보장법에 따라 사업주를 대신해 국가가 근로자에게 먼저 지급하는 임금등이다.","r":[]},"대지급금":{"d":"사업주가 임금등을 주지 못할 때 고용노동부장관이 근로자에게 대신 지급하는 금액이다.","r":[]},"도산등사실인정":{"d":"사업이 폐업 등으로 임금을 지급할 능력이 없다는 사실을 고용노동부장관이 인정하는 것이다.","r":[]},"대위":{"d":"제3자가 채무자를 대신해 변제한 뒤 채권자의 권리를 대신 행사하는 것이다.","r":[]},"임금채권보장기금":{"d":"사업주가 내는 부담금으로 조성해 대지급금 지급 등 임금채권보장사업에 쓰는 기금이다.","r":[]},"우리사주조합":{"d":"근로자가 자기 회사 주식을 취득하고 보유하기 위해 만든 조합이다.","r":[]},"기금법인":{"d":"사내근로복지기금을 운영하기 위해 설립하는 법인이다.","r":[]},"근로복지시설":{"d":"근로자의 복지를 위해 설치하는 시설로 근로자의 소득수준과 가족관계에 따라 이용자를 제한하거나 이용료를 차등할 수 없다.","r":[]},"외국인력정책위원회":{"d":"외국인근로자의 도입 규모와 송출국가의 지정 등을 심의하고 의결하는 위원회이다.","r":[]},"고용허가":{"d":"외국인근로자를 고용하려는 사용자에게 직업안정기관의 장이 내주는 허가이다.","r":[]},"표준근로계약서":{"d":"외국인근로자를 고용하는 사용자가 근로계약을 체결할 때 고용노동부령에 따라 사용하는 서식이다.","r":[]},"사증발급인정서":{"d":"외국인이 입국하기 전에 법무부장관이 사증 발급을 인정하는 서류이다.","r":[]},"송출국가":{"d":"외국인근로자를 우리나라로 보내는 나라이다.","r":[]},"출국만기보험":{"d":"외국인근로자가 귀국할 때 출국만기 시점에 퇴직금에 해당하는 금액을 지급받도록 사업주가 가입하는 보험이다.","r":[]},"직업안정기관":{"d":"직업소개, 구인과 구직 지원 등을 하는 고용노동부 소속 기관이다.","r":[]},"구인신청":{"d":"근로자를 구하려는 자가 직업안정기관에 구인 조건을 밝히고 하는 신청이다.","r":[]},"직업적성검사":{"d":"구직자의 직업적 성향과 능력을 알아보기 위해 하는 검사이다.","r":[]},"유료직업소개사업":{"d":"구인자나 구직자에게 소개 수수료를 받고 직업을 소개하는 사업이다.","r":[]},"무료직업소개사업":{"d":"수수료를 받지 않고 직업을 소개하는 사업이다.","r":[]},"선급금":{"d":"서비스를 제공하기 전에 미리 받는 금액이다.","r":[]},"적극적 고용개선조치":{"d":"현존하는 남녀 간의 고용차별을 없애거나 평등을 촉진하기 위해 잠정적으로 특정 성을 우대하는 조치이다.","r":[]},"직장 내 성희롱":{"d":"사업주나 상급자 또는 근로자가 직장에서 지위를 이용하거나 업무와 관련해 다른 근로자에게 성적 언동을 하는 행위이다.","r":[]},"입증책임":{"d":"소송에서 주장하는 사실이 있음을 증명해야 하는 책임이다.","r":[]},"가족돌봄등근로시간단축":{"d":"가족 돌봄 등을 이유로 근로자가 신청하면 근로시간을 줄여 주는 제도이다.","r":[]},"육아기 근로시간 단축":{"d":"육아를 위해 근로자가 신청하면 근로시간을 줄여 주는 제도이다.","r":[]},"난임치료":{"d":"인공수정 등으로 임신을 시도하는 치료로 근로자는 이를 이유로 휴가를 청구할 수 있다.","r":[]},"명예고용평등감독관":{"d":"사업장의 남녀고용평등 이행을 촉진하기 위해 근로자 중에서 위촉하는 감독관이다.","r":[]},"차별적 처우":{"d":"같은 종류의 업무를 하는 비교 대상 근로자에 비해 합리적 이유 없이 불리하게 대우하는 것이다.","r":[]},"시정명령":{"d":"노동위원회가 차별적 처우에 해당한다고 판정할 때 사업주에게 내리는 명령이다.","r":[]},"파견근로자":{"d":"파견사업주에게 고용되어 사용사업주의 지휘와 명령을 받아 근로하는 사람이다.","r":[]},"사용사업관리책임자":{"d":"사용사업주가 파견근로자를 지휘하고 관리하기 위해 선임하는 책임자이다.","r":[]},"쟁의행위":{"d":"파업, 태업 등 노동조합이 주장을 관철하려고 업무의 정상적 운영을 저해하는 행위이다.","r":[]},"최저임금위원회":{"d":"최저임금의 심의와 결정에 관한 사항을 다루며 근로자위원, 사용자위원, 공익위원으로 구성하는 위원회이다.","r":[]},"최저임금안":{"d":"최저임금위원회가 심의해 의결해 고용노동부장관에게 제출하는 최저임금의 안이다.","r":[]},"재심의":{"d":"고용노동부장관이 최저임금안에 따라 결정하기 어려운 경우 위원회에 다시 심의해 달라고 요청하는 절차이다.","r":[]},"상임위원":{"d":"위원회에서 상근하며 업무를 맡는 위원이다.","r":[]},"확정급여형퇴직연금제도":{"d":"근로자가 받을 급여의 수준이 사전에 결정되어 있는 퇴직연금제도이다.","r":[]},"확정기여형퇴직연금제도":{"d":"사용자가 부담할 부담금이 사전에 정해져 있고 그 운용 결과에 따라 급여가 달라지는 퇴직연금제도이다.","r":[]},"퇴직금 중간정산":{"d":"근로자가 퇴직하기 전에 계속근로기간에 대한 퇴직금을 미리 정산해 지급하는 것이다.","r":[]},"퇴직연금사업자":{"d":"퇴직연금제도의 적립금을 운용하고 관리하는 금융기관이다.","r":[]},"적립금운용위원회":{"d":"퇴직연금제도 적립금의 합리적인 운용을 위해 사용자가 구성하는 위원회이다.","r":[]},"중도인출":{"d":"확정기여형퇴직연금제도에 가입한 근로자가 일정한 사유가 있을 때 적립금을 퇴직 전에 꺼내 쓰는 것이다.","r":[]},"중소기업퇴직연금기금제도":{"d":"중소기업 근로자의 퇴직연금을 공동으로 적립하고 운용하는 제도이다.","r":[]},"가입기간":{"d":"퇴직연금제도에서 급여 산정과 수급 요건의 기준이 되는 기간이다.","r":[]}},"notes":{"15세 미만인 사람(중학교 재학 중인 18세 미만 포함)은 고용노동부장관의 취직인허증이 있어야 사용할 수 있고, 13세 미만은 예술공연 참가의 경우에만 받을 수 있다":"15세 미만자는 취직인허증이 있어야 고용할 수 있고 13세 미만은 예술공연 참가의 경우에만 받을 수 있습니다.","15세 이상 18세 미만인 사람의 근로시간은 1일 7시간, 1주 35시간을 넘지 못한다":"연소자의 근로시간은 성인보다 짧게 하루 7시간, 주 35시간이 상한입니다.","18세 미만인 사람과 계약할 때 근로조건(취업 장소·업무 포함)은 전자문서를 포함한 서면으로 명시·교부한다":"18세 미만자와 계약할 때는 취업 장소와 업무를 포함한 근로조건을 전자문서를 포함한 서면으로 명시해 교부합니다.","18세 미만인 사람을 사용하면 연령을 증명하는 가족관계기록사항 증명서와 친권자 또는 후견인의 동의서를 사업장에 갖추어 둔다":"18세 미만자를 쓰면 연령 증명 서류와 친권자·후견인의 동의서를 사업장에 갖춰 둡니다.","18세 미만인 자와 계약하면 근로조건을 서면으로 명시하여 교부한다":"18세 미만자와 계약할 때는 근로조건을 서면으로 명시해 교부하는 것이 의무입니다.","18세 이상 임신 중인 여성에게도 적용할 수 있다":"18세 이상 임신 중 여성에게도 선택적 근로시간제를 적용할 수 있습니다.","1개월을 넘는 주기로 정기 지급되어도 통상임금이 될 수 있다":"지급 주기가 길어도 정기적·일률적으로 지급하기로 했다면 통상임금이 될 수 있습니다.","1년간 80% 이상 출근하면 15일을 준다":"1년간 80% 이상 출근하면 연차휴가 15일이 발생합니다.","1년 이상 계약한 수습 근로자는 수습 3개월 이내에 감액할 수 있지만 1년 미만 계약자에게 낮은 최저임금을 정할 수는 없다":"수습 근로자의 감액은 1년 이상 계약일 때 3개월 이내로 한정되고 1년 미만 계약자에게는 허용되지 않습니다.","1일 소정근로시간 수는 4주 동안의 소정근로시간을 그 기간의 통상근로자 총 소정근로일 수로 나눈 시간이다(분모를 ‘단시간근로자의 소정근로일 수’로 바꾼 선지가 나왔다)":"단시간근로자의 1일 소정근로시간은 4주 소정근로시간을 통상근로자의 소정근로일 수로 나누어 구합니다.","1주 소정근로일을 개근하면 1주 평균 1회 이상 유급휴일을 주며 일요일로 정해야 하는 것은 아니다":"주휴일은 개근한 근로자에게 주 1회 이상 유급으로 주는 휴일이고 요일은 일요일로 정하지 않아도 됩니다.","2019년 기출의 ‘5일 범위 3일 이상’과 2024년 기출의 ‘3일·최초 1일’은 개정 전 내용이다":"이전 기출의 일수는 개정 전 내용이라 지금은 맞지 않습니다.","3년 이상 계속근로하면 최초 1년을 넘는 2년마다 1일을 더하고 총 일수는 25일이 한도다":"3년 이상 계속근로하면 최초 1년을 넘는 2년마다 1일씩 더하며 총 25일을 넘지 않습니다.","4주 평균 1주 소정근로시간이 15시간 미만인 근로자에게는 주휴일과 연차 유급휴가가 적용되지 않는다":"주 평균 15시간 미만으로 일하는 초단시간 근로자는 주휴일과 연차 유급휴가의 적용에서 빠집니다.","55세 이상 근로자의 은퇴 준비 단축 중 근로자가 명시적으로 청구하면 주 12시간 이내 연장근로를 시킬 수 있다":"은퇴 준비를 위해 단축한 근로자도 본인이 명시적으로 청구하면 주 12시간 이내에서 연장근로를 할 수 있습니다.","6개월 이내이며 근로일 사이 11시간 연속 휴식을 보장하고, 15세 이상 18세 미만자와 임신 중인 여성에게는 탄력적 근로시간제를 적용하지 않는다":"이 단위는 근로자 건강을 위해 6개월 이내로 하고 연속 휴식 11시간을 주며 연소자·임신부는 제외합니다.","‘사전협의’로 바꾼 선지가 출제됐다":"동의가 필요한 사항을 사전협의로 바꾼 설명은 틀립니다.","가사·학업 등을 이유로 근로자가 단시간근로를 신청하면 단시간근로자로 전환하도록 노력한다":"가사나 학업 등으로 근로자가 단시간근로를 원해 신청하면 사용자가 그렇게 바꾸도록 노력해야 합니다.","가족돌봄 등 근로시간 단축은 주 15시간 이상 30시간 이하다":"가족돌봄 등 근로시간 단축의 단축 후 근로시간은 주 15시간 이상 30시간 이하로 육아기 단축과 상한이 다릅니다.","가족돌봄휴직은 연간 최장 90일이다(60일 X)":"가족돌봄휴직은 연간 최장 90일이며 60일이 아닙니다.","감급 1회 금액은 평균임금 1일분의 2분의 1을, 총액은 1임금지급기 임금 총액의 10분의 1을 넘지 못한다":"감급은 지나치게 깎이지 않게 1회에는 평균임금 일급의 절반, 총액에는 임금 총액의 10분의 1이라는 상한이 있습니다.","감시·단속적 근로는 서면 합의가 아니라 장관 승인이 요건이다":"감시·단속적 근로의 적용 제외는 서면 합의가 아니라 고용노동부장관 승인이 요건입니다.","같은 정도의 비위에 대해 기준과 어긋나게 과중한 징계를 하면 위법이다":"같은 정도의 비위에 기준과 달리 과중하게 징계하면 위법입니다.","건강관리카드 소지자는 산재 요양급여 신청 때 카드로 의학적 소견서 제출을 대신할 수 있다":"건강관리카드가 있으면 산재 요양급여를 신청할 때 따로 소견서를 내지 않아도 카드로 갈음합니다.","결과와 조치사항은 위험성 결정 내용을 포함하여 기록하고 3년간 보존한다":"평가 결과와 조치사항은 기록으로 남겨 3년 보존해야 나중에 확인할 수 있습니다.","경영 악화를 막기 위한 사업의 양도·인수·합병은 긴박한 경영상 필요로 본다":"경영 악화를 막으려는 사업의 양도·인수·합병도 긴박한 경영상 필요로 인정됩니다.","계속근로 1년 미만이거나 1년간 80% 미만 출근한 근로자에게는 1개월 개근 시 1일을 준다":"출근율이 낮거나 1년이 안 된 근로자도 1개월을 개근하면 연차 1일을 받습니다.","계속 근로한 기간이 3개월 미만인 경우, 천재·사변 등 부득이한 사유로 사업 계속이 불가능한 경우, 근로자가 고의로 사업에 막대한 지장이나 재산상 손해를 끼친 경우로서 고용노동부령이 정하는 경우":"3개월 미만 근속이나 부득이한 사업 중단, 근로자의 고의 손해는 해고예고를 하지 않아도 됩니다.","계속하여 30일 이상 근무한 근로자는 퇴직 후 3년 이내에 사용증명서를 청구할 수 있고 사용자는 사실대로 적어 즉시 내준다":"일정 기간 일한 사람이 구직에 쓰도록 퇴직 후 3년 안에 사용증명서를 청구하면 사용자가 사실대로 발급해야 합니다.","고객의 폭언 등으로 고객응대근로자에게 건강장해가 생기거나 생길 우려가 크면 업무의 일시 중단·전환 등을 한다":"고객의 폭언으로 건강에 해가 생길 우려가 크면 업무를 잠시 멈추거나 다른 일로 바꿔 줍니다.","고령자(55세 이상)는 2년을 넘어 파견할 수 있고, 사용사업주는 직접 고용하려는 업무의 파견근로자를 우선 고용하도록 노력한다":"고령자는 2년을 넘겨 파견할 수 있고 사용사업주는 직접 고용하려는 업무의 파견근로자를 먼저 고용하려 노력합니다.","고용노동부와 소속 기관에 두며 사업장·기숙사를 현장조사하고 장부·서류 제출을 요구하며 사용자와 근로자를 심문할 수 있다":"근로감독관은 사업장과 기숙사를 현장조사하고 장부·서류 제출을 요구하며 사용자와 근로자를 심문할 수 있습니다.","고용노동부장관은 근로자의 생계비와 임금실태를 매년 조사한다(격년 X)":"장관은 최저임금 기초 자료를 위해 생계비와 임금실태를 매년 조사하며 격년이 아닙니다.","고용노동부장관은 명단 공개 전에 3개월 이상의 기간을 정하여 소명 기회를 준다":"명단 공개 전에 장관은 3개월 이상 소명 기회를 주어 체불사업주가 반박할 수 있게 합니다.","고용노동부장관이 매년 3월 31일까지 최저임금위원회에 심의 요청":"고용노동부장관은 최저임금 결정 절차를 시작하려고 매년 3월 31일까지 위원회에 심의를 요청합니다.","고용허가서 발급일부터 3개월 이내에 표준근로계약서로 계약하고 근로계약 효력은 입국한 날부터 생기며, 취업활동 기간은 입국일부터 3년이고 입국 후 15일 이내에 취업교육을 받는다":"발급일부터 3개월 안에 표준근로계약서로 계약하고 효력은 입국일부터이며 취업활동은 입국일부터 3년입니다.","공민권 행사에 필요한 시간을 청구받으면 거부하지 못하고, 직무 수행에 지장이 없는 범위에서 청구한 시간을 변경할 수 있을 뿐이다":"근로자가 투표 등 공민권 행사 시간을 청구하면 사용자는 거부할 수 없고 업무에 지장이 없게 시간만 바꿀 수 있습니다.","과반수 노조와 협의했으면 해고 대상 직원들만의 대표와 따로 협의하지 않아도 되고, 형식상 자격이 부족해도 실질적으로 근로자 의사를 반영하는 대표와 협의했으면 절차 요건을 충족한다":"과반수 노조와 협의했다면 해고 대상자들만의 대표와 따로 협의하지 않아도 되고 실질적으로 근로자 의사를 반영하는 대표면 충분합니다.","관공서 공휴일(일요일 제외)은 유급으로 보장하되 근로자대표와 서면 합의하면 특정한 근로일로 대체할 수 있다":"관공서 공휴일은 유급휴일로 보장하되 근로자대표와 서면 합의로 다른 근로일과 맞바꿀 수 있습니다.","구제명령, 기각결정, 재심판정은 재심 신청이나 행정소송 제기로 효력이 정지되지 않는다":"판정이 나와도 재심이나 소송을 제기하면 효력이 정지되는 것이 아니라 그대로 유지됩니다.","구제명령을 이행기한까지 이행하지 않은 사용자에게 3천만원 이하의 이행강제금을 부과한다":"이행강제금은 구제명령을 어긴 사용자에게 3천만원을 한도로 부과하는 금전 제재입니다.","구제명령을 이행하면 새로운 이행강제금은 부과하지 않지만 이미 부과된 것은 징수한다":"구제명령을 이행하면 새 이행강제금은 안 매기지만 이미 부과한 것은 징수합니다.","국가는 사회적·경제적 방법으로 고용의 증진과 적정임금의 보장에 노력하여야 하고, 법률이 정하는 바에 따라 최저임금제를 시행하여야 한다":"헌법은 국가가 고용 증진과 적정임금 보장에 힘쓰고 최저임금제를 법률대로 시행하도록 정하고 있습니다.","국가에 대한 직접적인 직장존속보장청구권은 인정되지 않으므로 근로관계 당연승계 입법 의무도 없다":"근로의 권리가 있어도 국가에 직장을 지켜 달라고 직접 청구할 수는 없어 근로관계를 승계하는 입법 의무도 생기지 않습니다.","국가와 지방자치단체에도 적용된다":"국가와 지방자치단체가 사용자일 때도 근로기준법의 적용 대상입니다.","국가유공자·상이군경 및 전몰군경의 유가족이 우선적으로 근로의 기회를 받으며 ‘전몰군경’ 본인이나 ‘근로의 의무’로 바꾸면 틀린다":"국가유공자·상이군경·전몰군경의 유가족이 우선 근로 기회를 받는 것이며 본인이나 근로의 의무로 바꾸면 틀립니다.","국내 무료직업소개는 시장·군수·구청장에게 신고, 국외 무료직업소개는 고용노동부장관에게 신고한다":"무료직업소개는 국내는 시장·군수·구청장에게, 국외는 장관에게 신고하는 방식입니다.","국내 유료직업소개는 시장·군수·구청장에게 등록, 국외 유료직업소개는 장관에게 등록한다":"유료직업소개는 국내는 시장·군수·구청장에게, 국외는 장관에게 등록해야 합니다.","그만둔 뒤에도 직무상 비밀을 지켜야 하고, 근로기준법 위반죄에 관하여 사법경찰관 직무를 수행한다":"근로감독관은 퇴직 후에도 직무상 비밀을 지켜야 하고 근로기준법 위반죄에서는 사법경찰관 직무를 합니다.","그 부분에 한정하여 무효이고 전부 무효가 아니다":"근로기준법에 못 미치는 근로계약은 미달한 부분만 무효이고 계약 전체가 무효가 되는 것은 아닙니다.","근기법에 따른 현장조사·서류 제출·심문 등의 수사는 검사와 근로감독관이 전담하되 근로감독관 직무에 관한 범죄 수사는 예외다":"근로기준법에 따른 수사는 검사와 근로감독관이 전담하며 근로감독관 직무에 관한 범죄 수사는 예외입니다.","근로감독관이 위반 사실을 고의로 묵과하면 3년 이하 징역 또는 5년 이하 자격정지이고, 사용자나 그 배우자·4촌 이내 혈족·인척인 근로자가 직장 내 괴롭힘을 하면 1천만원 이하 과태료다":"근로감독관이 위반을 고의로 눈감으면 3년 이하 징역 또는 5년 이하 자격정지이고 사용자 친족이 괴롭힘을 하면 1천만원 이하 과태료입니다.","근로계약기간 만료나 정년으로 원직복직이 불가능해도 금품 지급을 명할 수 있다(2021 개정)":"계약기간 만료나 정년으로 원직복직이 불가능해도 2021년 개정으로 금품 지급을 명할 수 있게 됐습니다.","근로계약 불이행에 대한 위약금이나 손해배상액을 예정하는 계약은 금지된다":"근로계약을 어기면 위약금을 내거나 손해배상액을 미리 정하는 계약은 금지됩니다.","근로계약서, 임금대장, 고용·해고 서류 등은 3년간 보존하고, 임금대장은 마지막으로 써 넣은 날부터, 근로계약서는 근로관계가 끝난 날부터 기산한다":"계약서와 임금대장은 3년 보존하며 기산점은 임금대장은 마지막 기재일, 계약서는 근로관계 종료일입니다.","근로계약은 친권자·후견인이 대리하지 못하고, 불리한 계약은 친권자·후견인·고용노동부장관이 해지할 수 있다":"미성년자 근로계약은 본인이 맺고 불리하면 친권자·후견인·장관이 해지할 수 있어 대리는 허용되지 않습니다.","근로관계는 원칙적으로 포괄 승계되며 일부 근로자를 빼는 특약은 해고이므로 정당한 이유가 있어야 한다":"근로관계는 원칙적으로 통째로 승계되고 일부 근로자를 빼는 특약은 해고에 해당해 정당한 이유가 필요합니다.","근로관계 당사자는 근로기준법의 기준을 이유로 근로조건을 낮출 수 없다":"이 법의 기준을 핑계로 이미 정한 근로조건을 낮추는 것은 허용되지 않습니다.","근로관계 종료 후의 권리·의무도 근로자의 대우에 관한 사항이면 근로조건에 해당한다":"퇴직한 뒤 권리·의무도 근로자 대우와 관련되면 근로조건으로 봅니다.","근로복지공단(업무상 재해자 대상), 한국장애인고용공단(장애인 대상) 등은 신고 없이 무료직업소개를 할 수 있다":"근로복지공단과 한국장애인고용공단 등은 신고 없이 무료직업소개를 할 수 있습니다.","근로복지시설 운영자는 소득수준, 가족관계 등을 고려하여 이용자를 제한하거나 이용료를 차등할 수 있다(세 차례 X 선지로 출제)":"근로복지시설 운영자는 소득수준과 가족관계 등에 따라 이용자를 제한하거나 이용료를 차등할 수 있습니다.","근로시간은 1주 40시간, 1일 8시간이고 당사자 합의로 1주 12시간까지 연장할 수 있다":"법정 근로시간은 1주 40시간과 1일 8시간이며 합의해도 연장은 1주 12시간이 한도입니다.","근로시간이 4시간이면 30분 이상, 8시간이면 1시간 이상의 휴게를 근로시간 도중에 준다":"4시간 근무에는 30분 이상, 8시간 근무에는 1시간 이상의 휴게를 근로시간 도중에 줘야 합니다.","근로의 권리는 자연인의 권리이고 법인은 주체가 될 수 없다":"근로의 권리는 사람에게만 인정되는 권리라서 법인은 주체가 될 수 없습니다.","근로자가 받을 급여 수준이 미리 정해진 제도다":"확정급여형은 받을 급여가 미리 정해져 있어 운용 위험을 사용자가 집니다.","근로자가 원직복직을 원하지 않으면 노동위원회는 원직복직 대신 해고기간 임금 상당액 이상의 금품 지급을 명할 수 있다":"금전보상은 근로자가 복직을 원하지 않을 때 노동위원회가 임금 상당액 이상의 금품을 대신 주게 하는 제도입니다.","근로자가 임금채권을 양도했더라도 사용자는 양수인에게 지급할 수 없고 양수인도 사용자에게 직접 청구하지 못한다":"임금은 근로자 본인이 직접 받아야 하므로 채권을 양도해도 양수인이 사용자에게 받아 갈 수 없습니다.","근로자가 출산, 질병, 재해, 혼인, 사망 등 비상한 경우의 비용에 쓰려고 청구하면 지급기일 전이라도 이미 제공한 근로에 대한 임금을 지급한다":"출산·질병·혼인·사망 같은 비상한 경우 비용을 위해 청구하면 지급기일 전이라도 이미 일한 임금을 줍니다.","근로자공급사업은 고용노동부장관의 허가를 받아야 하고 국내 근로자공급사업은 노동조합이 허가를 받을 수 있으며 파견사업은 근로자공급사업에서 빠진다":"근로자공급사업은 장관의 허가를 받아야 하고 국내에서는 노동조합이 허가받을 수 있으며 파견사업은 포함되지 않습니다.","근로자대표가 요구하면 건강진단과 작업환경측정에 근로자대표를 참석시킨다":"근로자대표가 요구하면 건강진단과 작업환경측정에 직접 참관하게 하여 투명성을 높입니다.","근로자 대표와 사용자 대표가 고시일부터 10일 이내에 이의 제기(30일 X)":"근로자 대표와 사용자 대표는 고시일부터 10일 안에 이의를 제기할 수 있으며 30일이 아닙니다.","근로자대표와 서면 합의로 정하고 특정 주 52시간, 특정 일 12시간이 한도다":"이 단위는 서면 합의가 있어야 하고 특정 주와 특정 일의 상한이 앞 단위보다 엄격하게 52시간, 12시간입니다.","근로자대표와 서면 합의로 정한 시간을 근로한 것으로 본다":"재량근로는 실제 일한 시간이 아니라 근로자대표와 서면 합의로 정한 시간을 근로한 것으로 봅니다.","근로자대표와 서면 합의하면 12시간을 넘는 연장과 휴게 변경이 가능한 특례업종은 육상운송(노선버스 제외)·수상운송·항공운송·기타 운송관련 서비스·보건업의 5개다":"서면 합의로 12시간을 넘는 연장과 휴게 변경이 가능한 특례업종은 육상운송 등 5개로 정해져 있습니다.","근로자대표와 서면 합의하면 연장·야간·휴일근로 임금 대신 휴가를 줄 수 있고 고용노동부장관 승인은 필요 없다":"서면 합의가 있으면 연장·야간·휴일근로 임금 대신 보상휴가를 줄 수 있고 장관 승인은 필요 없습니다.","근로자대표와 서면 합의하면 연차휴가일을 갈음하여 특정 근로일에 휴무시킬 수 있다":"서면 합의가 있으면 연차휴가일을 갈음하여 특정 근로일에 쉬게 하는 연차 대체가 가능합니다.","근로자를 사용하는 모든 사업에 적용한다":"최저임금법은 근로자를 사용하는 모든 사업에 적용됩니다.","근로자를 해고하려면 적어도 30일 전에 예고하고, 예고하지 않으면 30일분 이상의 통상임금을 지급한다":"해고하려면 30일 전에 예고해야 하고 하지 않으면 30일분 이상의 통상임금을 대신 지급합니다.","근로자의 대리인에게 임금을 지급하면 직접불 원칙 위반이다":"근로자의 대리인에게 임금을 주는 것은 직접불 원칙을 어기는 것입니다.","근로자 측과 성실한 협의를 거쳤는지는 판단 요소의 하나다":"근로자 측과 성실하게 협의했는지가 전직 정당성 판단 요소의 하나입니다.","근로자파견사업은 고용노동부장관의 허가를 받아야 한다":"파견사업은 근로자 보호를 위해 장관의 허가를 받은 사업주만 할 수 있습니다.","근로조건·근로형태·직종 등의 특수성에 따라 일부 근로자에게 적용되는 별도 취업규칙을 만들 수 있다":"근로조건과 직종 등이 다른 일부 근로자에게만 적용하는 별도의 취업규칙을 만들 수 있습니다.","근로조건의 기준은 인간의 존엄성을 보장하도록 법률로 정한다":"근로조건의 기준은 인간의 존엄성을 보장하는 수준으로 법률이 정합니다.","금융보험업은 특례에서 빠졌다(2018 개정)":"금융보험업은 2018년 개정으로 특례업종에서 빠졌습니다.","기간제 근로계약에서 갱신에 대한 정당한 기대권이 인정되면 합리적 이유 없는 갱신 거절은 효력이 없다":"기간제에서 갱신을 기대할 만한 사정이 있으면 합리적 이유 없는 갱신 거절은 무효입니다.","기간제근로자는 2년을 넘어 사용할 수 없고, 넘으면 기간의 정함이 없는 근로자로 본다":"기간제근로자를 2년 넘게 쓰면 기간의 정함이 없는 근로자로 간주합니다.","기간제근로자만 가질 수 있는 속성을 원인으로 한 불리한 처우도 기간제임을 이유로 한 차별이고, 노동위원회는 신청인이 주장한 비교대상자와 동일성이 인정되는 범위에서 적합한 비교대상자를 고를 수 있다":"기간제만 가질 수 있는 속성을 이유로 한 불리한 처우도 기간제임을 이유로 한 차별이고 노동위원회는 적합한 비교대상자를 고를 수 있습니다.","기간제·단시간근로자가 차별적 처우가 있은 날(계속되는 차별은 종료일)부터 6개월 이내에 노동위원회에 시정 신청(3개월 X) · 차별 내용을 구체적으로 적는다":"차별 시정 신청은 차별적 처우가 있은 날 또는 계속되는 차별의 종료일부터 6개월 이내에 하며 3개월이 아닙니다.","기간제·단시간근로자와 계약할 때 근로계약기간, 근로시간·휴게, 임금, 휴일·휴가, 취업 장소와 업무를 서면으로 명시하고 ‘근로일 및 근로일별 근로시간’은 단시간근로자에게만 명시한다":"기간제·단시간근로자와 계약할 때 서면으로 밝힐 항목이 정해져 있으며 근로일별 근로시간은 단시간에게만 해당합니다.","기숙사규칙 작성·변경에는 기숙 근로자 과반수를 대표하는 자의 동의를 받는다(과반수의 동의 X)":"기숙사규칙은 기숙 근로자 과반수를 대표하는 사람의 동의를 받아 정하며 과반수의 동의를 받는 것이 아닙니다.","기준은 근로자의 의사이고 ‘사용자가 원하지 않으면’으로 바꾼 선지는 틀렸다":"금전보상은 근로자의 의사가 기준이라 사용자가 원하지 않으면으로 바꾼 설명은 틀립니다.","기출은 15일을 20일, 30일로 바꿔 냈다":"재심 신청과 행정소송 기한 숫자를 바꾸면 틀린 설명이 됩니다.","기출은 두 문장의 주어를 ‘근로의 권리’로 바꿔 틀린 선지로 냈다":"근로조건 기준과 근로의 의무 문장은 주어가 근로의 권리가 아니므로 주어를 바꾸면 틀린 설명이 됩니다.","긴박한 경영상 필요는 기업 전체의 경영사정을 놓고 해고 당시를 기준으로 판단하고, 장래 위기에 대비한 객관적으로 합리적인 감원도 포함된다":"긴박한 경영상 필요는 기업 전체 경영사정으로 해고 당시를 기준으로 보며 장래 위기에 대비한 합리적 감원도 포함합니다.","난임치료휴가는 연간 6일이고 최초 2일이 유급이다(2025 개정)":"난임치료휴가는 연간 6일이고 처음 2일은 유급입니다.","내정 취소가 무효이면 내정자는 취업하였다면 받았을 임금을 청구할 수 있다":"무효인 내정 취소로 일을 못 한 내정자는 일했다면 받았을 임금 상당액을 사용자에게 요구할 수 있습니다.","노동위원회가 심문 중 쌍방 또는 일방의 신청이나 직권으로 조정 절차 시작 · 조정 신청은 시정신청일부터 14일 이내가 원칙이지만 노동위원회 승낙이 있으면 그 뒤에도 가능":"노동위원회는 심문 중 신청이나 직권으로 조정 절차를 시작할 수 있고 조정 신청은 시정신청일부터 14일이 원칙입니다.","노동위원회가 지체 없이 조사하고 관계 당사자를 심문":"노동위원회는 신청을 받으면 지체 없이 조사하고 관계 당사자를 심문합니다.","노동위원회는 차별 등이 인정되면 시정명령을 하고 고용노동부장관은 확정된 명령의 이행상황 제출을 요구할 수 있다":"차별이 인정되면 노동위원회가 시정명령을 하고 장관은 확정된 명령의 이행상황 제출을 요구할 수 있습니다.","노무 제공 중 생명·신체를 해치지 않도록 보호할 의무는 근로계약에 따르는 신의칙상 부수적 의무다":"근로자의 생명과 신체를 해치지 않도록 보호할 의무는 계약에 따른 신의칙상 부수의무입니다.","노조가 불리하게 바뀐 취업규칙을 따르기로 단체협약을 맺으면 기존 근로자에게도 적용된다":"노조가 단체협약으로 불리하게 바뀐 취업규칙을 따르기로 하면 기존 근로자에게도 적용됩니다.","노조 간부 징계에 노조와 합의하도록 단체협약에 정했다면 합의 없이 한 징계는 원칙적으로 무효다":"단체협약에 노조 간부 징계를 노조와 합의하도록 했다면 합의 없는 징계는 원칙적으로 무효입니다.","농림·축산·수산업 종사자, 고용노동부장관 승인을 받은 감시·단속적 근로자, 사업 종류와 관계없이 관리·감독 또는 기밀 업무 종사자에게는 근로시간·휴게·휴일 규정을 적용하지 않는다":"농림·축산·수산업, 장관 승인을 받은 감시·단속적 근로자, 관리·감독·기밀 업무 종사자는 근로시간·휴게·휴일 규정에서 빠집니다.","누구든지 괴롭힘을 알게 되면 사용자에게 신고할 수 있으며 피해자 동의는 요건이 아니고 신고 의무도 아니다":"괴롭힘을 아는 사람은 누구든 신고할 수 있고 피해자 동의가 필요 없으며 신고는 의무가 아닙니다.","누구든지 법률에 따르지 않고 영리로 남의 취업에 개입하거나 중간인으로서 이익을 취득하지 못한다":"법률의 근거 없이 영리 목적으로 남의 취업에 끼어들어 이익을 얻는 중간착취가 금지됩니다.","누구든지 직장 내 성희롱 발생 사실을 사업주에게 신고할 수 있다":"피해자가 아니어도 누구나 직장 내 성희롱을 알면 사업주에게 신고할 수 있습니다.","누구든지 취업을 방해할 목적으로 비밀 기호나 명부를 작성·사용하거나 통신을 하지 못한다":"취업을 방해하려고 비밀 기호나 명부를 만들거나 통신하는 일은 금지됩니다.","다만 노조나 근로자가 동의권을 남용한 경우에는 동의 없이도 유효할 수 있고, 남용 여부는 법원이 직권으로 판단할 수 있다":"동의권을 남용해 변경을 막는 예외 상황이면 동의가 없어도 유효할 수 있고 법원이 직권으로 판단합니다.","단시간근로자에게만 적용되는 취업규칙을 불리하게 바꾸려면 그 단시간근로자 과반수의 동의를 받는다":"단시간근로자에게만 적용되는 취업규칙은 그 집단의 과반수가 동의해야 불리하게 고칠 수 있습니다.","단시간근로자에게 소정근로시간을 넘겨 일을 시키려면 동의가 필요하고 그 경우에도 1주 12시간을 넘지 못하며 초과근로에는 통상임금의 100분의 50 이상을 가산한다":"단시간근로자에게 초과근로를 시키려면 동의가 필요하고 1주 12시간을 넘지 못하며 통상임금의 100분의 50 이상을 가산합니다.","단위는 시간·일·주·월이고 ‘연’ 단위는 없다":"최저임금 단위는 시간·일·주·월이며 연 단위는 없고 일·주·월로 정해도 시간급으로 같이 표시합니다.","단체협약이 있어도 1일 2시간, 1주 6시간, 1년 150시간을 넘는 시간외근로를 시키지 못한다":"산후 1년 미만 여성에게는 단체협약이 있어도 1일 2시간, 1주 6시간, 1년 150시간을 넘는 시간외근로를 시킬 수 없습니다.","단축 후 근로시간은 주 15시간 이상 35시간 이하다(기출 X 선지는 ‘10시간 이상 30시간’)":"육아기 근로시간 단축 후 근로시간은 주 15시간 이상 35시간 이하입니다.","당사자 합의로 1일 1시간, 1주 5시간을 한도로 연장할 수 있다":"연소자도 합의하면 일정 시간 연장할 수 있으나 하루 1시간, 주 5시간으로 제한됩니다.","대법원 전원합의체는 집단적 동의가 없으면 사회통념상 합리성만으로 불리한 변경의 유효성을 인정할 수 없다고 했다":"집단 동의 없는 불리한 변경은 합리성이 있더라도 원칙적으로 유효하지 않다는 것이 대법원 전원합의체 입장입니다.","대상 업무가 아닌 곳에 쓰거나 2년을 넘겨 쓰면 사용사업주에게 직접고용 의무가 생기고, 직접고용한 것으로 간주되는 것은 아니다":"파견 대상이 아닌 업무나 2년을 넘긴 파견은 사용사업주에게 직접고용 의무를 지우지만 고용한 것으로 간주되지는 않습니다.","대상 업무는 신상품·신기술 연구개발, 정보처리시스템 설계·분석, 기사 취재·편집, 디자인·고안, 방송 프로듀서·감독, 회계·법률·특허·감정평가 등 사무다":"재량근로 대상은 연구개발, 시스템 설계, 취재·편집, 디자인, 방송 연출, 회계·법률·특허 등 업무 방식을 근로자가 정하는 직무입니다.","대상 자녀는 만 12세 이하 또는 초등학교 6학년 이하로 넓어졌다(2025 개정)":"육아기 근로시간 단축의 대상 자녀 범위는 개정으로 만 12세 이하 또는 초등학교 6학년 이하까지 넓어졌습니다.","도금·수은·납·카드뮴 등 일부 유해 작업은 도급이 금지되거나 고용노동부장관 승인을 받아야 하며 모든 유해·위험 작업이 허가 대상인 것은 아니다":"위험한 일부 유해 작업만 도급이 금지되거나 승인 대상이고 모든 유해 작업이 허가 대상은 아닙니다.","도급인 사업장에서 관계수급인 근로자가 작업하면 도급인이 작업환경측정을 하게 한다":"하청 근로자가 도급인 사업장에서 일하면 도급인이 작업환경측정을 책임지고 실시하게 합니다.","도급인에서 건설공사발주자는 빠지고, 관계수급인은 여러 단계 도급에서 각 단계별로 도급받은 사업주 전부다":"도급인에는 건설공사발주자가 들어가지 않고 관계수급인은 각 단계에서 도급받은 사업주 전부입니다.","도급인의 책임 있는 사유로 수급인이 최저임금 미만을 지급하면 도급인이 수급인과 연대하여 책임진다":"도급인 탓에 수급인이 최저임금 미만을 주면 도급인이 수급인과 연대하여 책임집니다.","도산대지급금은 파산선고등이나 도산등사실인정이 있은 날부터 2년 이내에 고용노동부장관에게 청구한다(3년·근로복지공단 X)":"도산대지급금은 파산선고등이나 사실인정일부터 2년 안에 고용노동부장관에게 청구하며 3년이나 근로복지공단이 아닙니다.","동거 친족만으로 이루어진 사업과 가사사용인에게는 법 전부를 적용하지 않고, 상시 4명 이하 사업은 일부 규정만 빠진다":"남녀고용평등법은 동거 친족 사업과 가사사용인에게는 전부 적용되지 않고 4명 이하 사업은 일부만 빠집니다.","동거하는 친족만 사용하는 사업과 가사사용인, 선원법이 적용되는 선원과 선박 소유자에게는 적용하지 않는다":"동거 친족만 쓰는 사업, 가사사용인, 선원법상 선원과 선박 소유자는 최저임금법 적용에서 빠집니다.","동거하는 친족만을 사용하는 사업과 가사 사용인에게는 적용하지 않는다":"가족끼리만 일하는 사업과 집안일을 돕는 가사 사용인은 근로기준법 적용에서 빠집니다.","동의 없이 바뀐 취업규칙도 변경 후 신규 입사자에게는 적용되고 현행 법규적 효력을 갖는 취업규칙은 변경된 것이다":"동의 없이 바뀐 취업규칙은 기존 근로자에게는 효력이 없고 변경 후 입사한 사람에게만 적용됩니다.","동일가치노동의 기준을 정할 때 노사협의회 근로자위원의 의견을 듣고, 임금차별 목적으로 세운 별개 사업은 동일 사업으로 본다":"같은 가치의 노동인지 판단 기준을 정할 때는 노사협의회 근로자위원 의견을 들으며 위장 분리 사업은 하나로 봅니다.","두 서류를 모두 두어야 하며 ‘또는’으로 바꾼 선지가 나왔다":"두 서류를 모두 갖춰야 하며 또는으로 바꾼 설명은 틀립니다.","만 8세 이하 또는 초등학교 2학년 이하 자녀를 위해 1년 이내로 쓰고, 부모가 각각 3개월 이상 쓰면 1년 6개월까지 늘어난다(2025 개정)":"육아휴직은 자녀 연령에 제한이 있으며 부모가 각각 3개월 이상 쓰면 총 기간이 1년 6개월까지 늘어납니다.","만료 시 ‘기간 만료’ 통지만 한 거부는 서면 통지 절차의 하자로 효력이 없다":"기간 만료라는 통지만으로 본계약을 거부하면 서면 통지 절차의 흠이 있어 효력이 없습니다.","명단은 3년간 게시하며 1년이 아니다":"체불사업주 명단의 게시 기간은 3년이므로 1년으로 바꾼 설명은 틀립니다.","명령한 날부터 30일 이내로 정한다(60일 X)":"구제명령 이행기한은 명령한 날부터 30일 이내로 정하며 60일이 아닙니다.","명부 기재사항이 바뀌면 지체 없이 정정한다":"명부 기재사항이 바뀌면 지체 없이 고쳐야 합니다.","명시된 근로조건이 사실과 다르면 근로자는 손해배상을 청구할 수 있고 즉시 근로계약을 해제할 수 있다":"계약 때 알려 준 조건이 실제와 다르면 근로자는 손해를 물을 수 있고 계약을 바로 끝낼 수 있습니다.","명시적 청구가 있고 고용노동부장관의 인가를 받아야 야간·휴일근로가 가능하다":"임신 중 여성은 명시적 청구와 장관 인가가 있어야 야간·휴일근로가 가능합니다.","모든 국민은 근로의 의무를 지고, 국가는 근로의 의무의 내용과 조건을 민주주의원칙에 따라 법률로 정한다":"근로의 의무는 모든 국민에게 있고 그 내용과 조건은 국가가 민주주의원칙에 따라 법률로 정합니다.","모집·채용에서 남녀를 차별하지 못하고 직무에 필요 없는 용모·키·체중 등 신체 조건이나 미혼 조건을 요구하지 못한다":"모집·채용에서 남녀를 차별할 수 없고 직무에 필요 없는 용모·키·체중이나 미혼 조건을 요구할 수 없습니다.","무자격위원이 참여한 징계의결은 그를 빼고 정족수가 되어도 무효이고, 원 징계 절차의 하자는 재심에서 보완되면 치유된다":"징계위원회에 자격 없는 위원이 참여하면 그를 빼고도 정족수가 되어도 의결은 무효이고 절차의 흠은 재심에서 보완되면 치유됩니다.","무주택자가 본인 명의로 주택을 사거나 전세금을 부담하는 경우, 본인·가족의 6개월 이상 요양, 파산·회생 등 법정 사유가 있으면 근로자 요구로 미리 정산할 수 있다":"무주택자의 주택 구입·전세금, 6개월 이상 요양, 파산·회생 등 법정 사유가 있어야 근로자 요구로 중간정산을 할 수 있습니다.","미성년자는 독자적으로 임금을 청구할 수 있고 임금 청구 소송도 독자적으로 할 수 있다":"미성년자는 임금을 독자적으로 청구할 수 있고 임금 청구 소송도 혼자 할 수 있습니다.","미성년자도 독자적으로 청구할 수 있고, 대지급금수급계좌의 예금 채권은 압류할 수 없다":"미성년자도 대지급금을 혼자 청구할 수 있고 수급계좌의 예금채권은 압류할 수 없습니다.","배우자 출산휴가는 20일 유급이고 출산일부터 120일 안에 청구하며 3회까지 나누어 쓸 수 있다(2025 개정)":"배우자 출산휴가는 유급으로 20일이며 출산일부터 120일 안에 청구하고 3회까지 나누어 쓸 수 있습니다.","법령이나 단체협약에 특별한 규정이 있으면 임금 일부를 공제하거나 통화 이외의 것으로 지급할 수 있다":"임금 전액·통화 지급 원칙에는 법령이나 단체협약이 정한 때 공제와 현물 지급이라는 예외가 있습니다.","법원 확정판결로 구제명령이 취소되면 부과·징수를 즉시 중지하고 이미 징수한 금액은 반환한다":"확정판결로 구제명령이 취소되면 이행강제금의 근거가 없어져 부과·징수를 멈추고 낸 금액도 돌려줍니다.","법인이면 대표자의 성명·나이·주소와 법인의 명칭·주소를 공개하고, 체불자료를 받은 종합신용정보집중기관은 이를 신용도 판단에 쓸 수 있다":"법인이면 대표자와 법인 정보를 공개하고 체불자료를 받은 종합신용정보집중기관은 신용도 판단에 쓸 수 있습니다.","본계약 거부는 보통의 해고보다 넓게 인정되지만 객관적으로 합리적인 이유와 사회통념상 상당성이 필요하다":"본계약 거부는 일반 해고보다 넓게 인정되지만 합리적 이유와 사회통념상 상당성이 있어야 합니다.","본인 동의만 있으면 야간·휴일근로를 시킬 수 있다":"성인 여성에게는 본인 동의만 있으면 야간·휴일근로를 시킬 수 있어 연소자보다 요건이 가볍습니다.","본인 동의와 고용노동부장관의 인가를 받아야 야간·휴일근로가 가능하다":"미성년자는 본인 동의에 더해 장관 인가가 있어야 야간·휴일근로를 할 수 있어 요건이 무겁습니다.","본인의 혼인 비용도 해당한다":"본인의 혼인 비용도 비상시 지급 청구 사유에 해당합니다.","부과 30일 전까지 문서로 미리 알리고, 부과할 때 액수·사유·납부기한 등을 문서로 통지하며 납부기한은 통지받은 날부터 15일 이내로 정한다":"이행강제금은 부과 30일 전에 문서로 예고하고 액수·사유·납부기한을 통지하며 납부기한은 통지일부터 15일 이내입니다.","부당해고가 성립하면 구제명령, 성립하지 않으면 기각결정 · 사용자와 근로자에게 각각 서면으로 통지":"부당해고가 성립하면 구제명령을 하고 성립하지 않으면 기각하며 양쪽에 서면으로 알립니다.","부득이한 사유로 사업 계속이 불가능하면 노동위원회의 승인을 받아 70% 미만을 줄 수 있다":"천재지변 같은 사정으로 사업이 불가능하면 노동위원회 승인을 받아 휴업수당을 70퍼센트 아래로 줄일 수 있습니다.","사내근로복지기금은 법인이고 자금을 차입할 수 없다":"사내근로복지기금은 독립된 법인이면서 외부에서 돈을 빌리는 차입은 하지 못합니다.","사생활의 비행도 기업의 사회적 평가를 해칠 염려가 있으면 징계사유가 된다":"근무시간 밖 비행도 회사의 평가를 떨어뜨릴 우려가 있으면 징계사유가 될 수 있습니다.","사실이 확인되면 피해근로자가 요청할 때 근무장소 변경 등을 하고, 행위자에게는 피해근로자의 의견을 들어 지체 없이 징계 등을 한다":"괴롭힘이 확인되면 피해근로자 의견을 들어 근무장소 변경 등 보호조치를 하고 행위자는 징계합니다.","사업 완료나 특정 업무 완성에 필요한 기간을 정한 경우, 휴직·파견 등 결원을 복귀 때까지 대신하는 경우, 학업·직업훈련, 55세 이상 고령자, 전문 지식·기술 활용 등은 2년을 넘어 쓸 수 있다":"사업 완료, 결원 대체, 학업·직업훈련, 55세 이상 고령자, 전문 지식 활용 등은 2년을 넘겨 쓸 수 있는 예외입니다.","사업주는 관계수급인 근로자를 포함한 근로자가 쓸 휴게시설을 갖춘다":"하청 근로자까지 이용할 수 있도록 사업주가 휴게시설을 마련해야 합니다.","사업주는 노사협의회가 추천하는 사람을 명예고용평등감독관으로 위촉할 수 있고 의무는 아니며 고용노동부장관은 기본계획을 5년마다 세운다":"명예고용평등감독관은 노사협의회가 추천하는 사람을 위촉할 수 있고 의무는 아니며 기본계획은 5년마다 세웁니다.","사업주는 산재 예방 능력을 갖춘 사업주에게 도급한다":"산재 예방 능력을 갖추지 못한 사업주에게 도급하면 안전 책임이 흐려지므로 능력을 갖춘 곳에 맡겨야 합니다.","사업주는 위험성평가를 할 때 해당 작업장 근로자를 참여시킨다":"위험성평가는 해당 작업장 근로자를 참여시켜 진행합니다.","사업주 부담금은 보수총액에 1천분의 2 범위에서 정한 비율을 곱한 금액이다(1천분의 3 X)":"사업주 부담금은 보수총액에 1천분의 2 범위의 비율을 곱한 금액이며 1천분의 3이 아닙니다.","사용기간 30일 미만인 일용근로자는 근로자 명부를 작성하지 않을 수 있다(기출 X 선지는 ‘3개월 미만’)":"30일 미만 일용근로자는 근로자 명부를 만들지 않아도 되고 기재사항이 바뀌면 바로 정정합니다.","사용자가 최저임금액, 산입하지 않는 임금, 적용 제외 근로자 범위, 효력발생일을 효력발생일 전날까지 근로자에게 알림":"사용자는 최저임금 관련 네 가지 사항을 효력발생일 전날까지 근로자가 알 수 있게 안내해야 합니다.","사용자 귀책사유로 휴업하면 평균임금의 100분의 70 이상을 지급하고, 그 금액이 통상임금을 넘으면 통상임금을 줄 수 있다":"사용자 탓에 쉬게 하면 평균임금의 100분의 70 이상을 휴업수당으로 주되 통상임금을 넘으면 통상임금만큼 줄 수 있습니다.","사용자는 근로자대표의 동의를 얻거나 의견을 들어 규약을 작성하고 고용노동부장관에게 신고하며 설정 전 근로기간도 가입기간에 넣을 수 있다":"확정급여형은 근로자대표 동의나 의견 청취로 규약을 만들어 장관에게 신고하며 설정 전 근로기간도 가입기간에 넣을 수 있습니다.","사용자는 기금 설립을 이유로 근로조건을 낮추거나 기존 근로복지 운영을 중단·감축하지 못한다":"기금을 세웠다는 이유로 근로조건을 낮추거나 기존 근로복지 운영을 줄일 수 없습니다.","사용자는 기숙사 생활의 자치에 필요한 임원 선거에 간섭하지 못한다":"기숙사 생활의 자치는 근로자가 맡으므로 사용자가 임원 선거에 끼어들 수 없습니다.","사용자는 대출금이나 불법행위 손해배상채권으로 임금채권과 상계하지 못한다":"사용자는 대출금이나 불법행위 손해배상채권을 가지고 있어도 임금과 상계할 수 없습니다.","사용자는 매년 1회 이상 연간 임금총액의 12분의 1 이상을 납입하고, 급여를 받을 권리는 양도·압류할 수 없다":"기금제도에서도 해마다 임금총액의 12분의 1 이상을 납입하며 급여를 받을 권리는 양도·압류가 안 됩니다.","사용자는 신고를 받거나 사실을 인지하면 지체 없이 객관적으로 조사하고, 조사 기간에는 필요하면 피해근로자 의사에 반하지 않게 근무장소 변경·유급휴가 등을 한다":"사용자는 신고를 받거나 알게 되면 지체 없이 객관적으로 조사하고 조사 기간에는 피해근로자 의사에 반하지 않게 보호조치를 합니다.","사용자는 최저임금을 이유로 종전 임금수준을 낮추지 못한다":"사용자는 최저임금을 지급한다는 이유로 종전 임금수준을 낮출 수 없습니다.","사용자는 통상근로자를 채용하려면 같은 업무의 단시간근로자를 우선 고용하도록 노력한다(‘우선 고용하여야’ X)":"통상근로자를 채용할 때 같은 업무의 단시간근로자를 먼저 고용하도록 노력하며 의무까지는 아닙니다.","사용자는 퇴직급여제도를 설정해야 하지만 계속근로기간이 1년 미만인 근로자와 4주 평균 1주 소정근로시간이 15시간 미만인 근로자는 제외된다":"퇴직급여제도 설정 의무는 계속근로 1년 미만자와 주 평균 15시간 미만 근로자에게는 적용되지 않습니다.","사용자 또는 근로자가 직장 내 지위나 관계의 우위를 이용하여 업무상 적정범위를 넘어 다른 근로자에게 신체적·정신적 고통을 주거나 근무환경을 악화시키는 행위다":"직장 내 괴롭힘은 지위나 관계의 우위를 이용해 업무상 적정범위를 넘어 고통을 주거나 근무환경을 악화시키는 행위입니다.","사유 없이 요구한다고 정산할 수 있는 것은 아니다":"법정 사유가 없으면 근로자가 요구해도 중간정산을 할 수 없습니다.","산업안전보건법은 국가·지방자치단체·공기업에도 적용된다":"산업안전보건법은 민간뿐 아니라 국가·지방자치단체·공기업에도 적용되는 법입니다.","산업안전보건위원회가 없으면 근로자대표의 동의를 받아 작성하고, 사고 조사와 대책 수립에 관한 사항이 들어가야 한다":"위원회가 없으면 근로자대표 동의를 얻어 안전보건관리규정을 작성하고 사고 조사와 대책 수립 사항을 담습니다.","산업재해는 노무를 제공하는 사람이 업무 관련 설비·원재료·가스·분진 등이나 작업으로 사망·부상·질병에 걸리는 것이다":"산업재해는 업무와 관련된 설비·원재료·분진 또는 작업 때문에 사망·부상·질병이 생기는 것입니다.","산업재해 발생의 급박한 위험이 있으면 즉시 작업을 중지시키고 근로자를 대피시킨다":"급박한 위험이 있으면 지체 없이 작업을 중지하고 근로자를 안전한 곳으로 옮겨야 합니다.","산정기간에 수습기간, 사용자 귀책 휴업기간, 출산전후휴가 기간, 업무상 부상·질병 요양기간, 육아휴직 기간, 쟁의행위 기간 등이 있으면 그 기간과 그 기간 중 받은 임금을 각각 뺀다":"수습, 휴업, 출산휴가, 요양, 육아휴직, 쟁의행위 기간은 불리한 계산을 막기 위해 기간과 임금을 모두 뺍니다.","산정사유 발생일 이전 3개월 동안 지급된 임금 총액을 그 기간의 총일수로 나눈 금액이다(분모를 ‘총 근로시간 수’로 바꾼 선지가 나왔다)":"평균임금은 산정사유 발생일 전 3개월간 임금 총액을 그 기간 총일수로 나눈 금액입니다.","산출액이 통상임금보다 적으면 통상임금을 평균임금으로 한다":"계산한 평균임금이 통상임금보다 적으면 통상임금을 평균임금으로 삼습니다.","상시 10명 미만 사업에서 근로자 동의나 요구로 개인형퇴직연금제도를 설정하면 퇴직급여제도를 설정한 것으로 본다":"10명 미만 사업장은 근로자 동의나 요구로 개인형퇴직연금제도를 만들면 퇴직급여제도를 갖춘 것으로 인정됩니다.","상시 10명 이상의 근로자를 사용하면 취업규칙을 작성하여 고용노동부장관에게 신고한다":"상시 10명 이상 근로자를 쓰면 취업규칙을 만들어 고용노동부장관에게 신고해야 합니다.","상시 4명 이하 사업에도 근로조건 명시(제17조)는 적용되지만 연차 유급휴가(제60조)와 공휴일 유급 보장은 적용되지 않는다":"4명 이하 사업장도 근로조건 명시는 해야 하지만 연차 유급휴가와 공휴일 유급 보장은 적용되지 않습니다.","상시 5명 이상 사업에 적용하고 동거 친족만 쓰는 사업은 제외한다":"기간제법은 상시 5명 이상 사업에 적용되고 동거 친족만 쓰는 사업은 적용되지 않습니다.","상시 5명 이상의 근로자를 사용하는 모든 사업에 적용되고 영리 여부나 1회적 사업인지는 묻지 않는다":"상시 5명 이상 근로자를 쓰는 사업이면 영리 목적이 없거나 일회성 사업이어도 근로기준법이 적용됩니다.","상임위원은 공익위원이 되고, 위원장과 부위원장은 공익위원 중에서 위원회가 선출한다":"상임위원은 공익위원이 되고 위원장과 부위원장은 위원회가 공익위원 중에서 뽑습니다.","생산고에 따른 임금이나 도급제 임금은 산정기간의 임금 총액을 그 기간의 총근로시간 수로 나누어 시간급을 구한다":"도급제 임금은 산정기간의 임금 총액을 총근로시간 수로 나눠 시간급으로 바꿔 비교합니다.","선원법 적용 선원에게는 이 법을 적용하지 않는다":"외국인근로자 고용법은 선원법이 적용되는 선원에게는 적용되지 않습니다.","선택적 복지제도도 직급·근속연수·부양가족에 따라 수혜 수준을 달리할 수 있다":"선택적 복지제도에서도 직급이나 근속, 부양가족 수에 따라 받는 수준을 다르게 둘 수 있습니다.","설립인가증을 받은 날부터 3주 이내에 설립등기를 하고, 기금협의회가 이사와 감사의 선임·해임을 협의·결정한다":"인가증을 받고 3주 안에 설립등기를 하고 이사·감사 선임과 해임은 기금협의회가 정합니다.","성희롱 행위자를 징계하지 않은 것은 신청 사유가 아니다":"행위자를 징계하지 않은 것은 시정 신청 사유에 해당하지 않아 노동위원회 신청 대상이 아닙니다.","소명 기회를 주면 충분하고 소명 자체나 개별 혐의마다 질문·진술이 반드시 있어야 하는 것은 아니며, 출석 통보는 소명을 준비할 상당한 기간을 두고 한다":"징계 절차에서는 소명의 기회를 주면 충분하고 출석 통보는 소명을 준비할 상당한 기간을 두고 해야 합니다.","소정근로시간을 넘는 근로의 대가와 주휴수당은 통상임금이 아니며, 통상임금 제외 합의는 법 기준에 미달하는 범위에서 무효다":"초과근로 대가와 주휴수당은 통상임금이 아니며 통상임금을 빼기로 한 합의는 법 기준에 못 미치는 만큼 무효입니다.","소정근로의 대가로 정기적·일률적으로 지급하기로 정한 임금이고, 대법원은 2024년 전원합의체에서 고정성을 요건에서 뺐다":"통상임금은 소정근로의 대가로 정기적·일률적으로 주기로 한 임금이고 고정성은 2024년 판결로 요건에서 빠졌습니다.","손해배상 청구는 노동위원회에 신청할 수도 있다":"명시 위반의 손해배상은 노동위원회를 통해서도 신청할 수 있습니다.","승계를 거부한 근로자는 양도 기업에 남고, 승계 후 퇴직금 규정이 불리하면 종전 규정이 적용된다":"영업양도에서 승계를 거부한 근로자는 양도 기업에 남고 승계되면 불리한 퇴직금 규정은 종전 규정을 적용합니다.","시간외근로를 시키지 못하고, 요구하면 쉬운 근로로 전환한다":"임신 중 여성에게는 시간외근로를 시킬 수 없고 요구하면 쉬운 근로로 전환해 줍니다.","시용기간을 명시하지 않았으면 정식 사원으로 채용된 것으로 본다":"시용기간을 계약에 명시하지 않았다면 처음부터 정식 사원으로 채용한 것으로 봅니다.","시용기간 중에도 확정적 근로관계는 존재하고 사용자에게 해약권이 유보되어 있을 뿐이다":"시용기간에도 근로관계가 확정되어 있고 사용자는 해약할 권리를 유보했을 뿐입니다.","신고자와 피해자에게 불리한 처우를 하면 안 되고 조사자는 비밀을 지키되 사용자 보고는 할 수 있다":"신고자·피해자는 불이익을 받지 않도록 보호되며 조사자는 비밀을 지키되 사용자에게는 보고할 수 있습니다.","신법 우선과 관계없이 무효다":"근로기준법에 미달하는 단체협약은 신법 우선과 관계없이 그 부분이 무효입니다.","신청은 학교장(의무교육 대상자·재학 중인 자) 및 친권자·후견인의 서명을 받아 사용자가 될 자와 연명으로 한다":"취직인허증 신청은 학교장과 친권자·후견인의 서명을 받아 사용자가 될 자와 연명으로 합니다.","신청은 휴직개시예정일 7일 전까지 철회할 수 있고 종료예정일 연기는 한 번만 가능하다":"신청 후에도 개시 예정일 7일 전까지는 철회할 수 있으며 종료 예정일은 한 번만 연기할 수 있습니다.","안전보건관리규정은 단체협약이나 취업규칙에 반할 수 없고, 반하는 부분은 단체협약·취업규칙을 따른다(방향을 뒤집은 선지가 나왔다)":"안전보건관리규정이 단체협약·취업규칙과 어긋나면 그 부분은 단체협약·취업규칙을 따릅니다.","야간근로 가산과 연차휴가 규정은 이들에게도 적용된다":"근로시간 규정이 적용되지 않는 사람에게도 야간근로 가산임금과 연차휴가 규정은 적용됩니다.","업무 관련 서류를 거짓으로 작성하거나 업무정지 기간 중에 업무를 하면 등록을 취소한다":"서류를 거짓으로 작성하거나 업무정지 중에 일하면 지도사 등록이 취소됩니다.","업무상 부상·질병 휴업기간, 출산전후휴가 기간, 육아휴직 기간은 출근한 것으로 본다":"업무상 부상·질병 휴업, 출산전후휴가, 육아휴직 기간은 출근한 것으로 보아 연차휴가 계산에 넣습니다.","여러 징계사유 중 일부만 인정되어도 나머지로 징계가 타당하면 유효하고, 그 증명책임은 사용자에게 있다":"징계사유가 여러 개일 때 일부만 인정돼도 나머지로 징계가 정당하면 유효하며 증명은 사용자가 합니다.","여성과 18세 미만인 사람은 갱내에서 근로시키지 못하지만 보건·의료, 보도·취재 등 일시적으로 필요한 업무는 예외다":"여성과 18세 미만자는 갱내 근로가 금지되지만 보건·의료, 보도·취재 등 일시적 필요 업무는 예외입니다.","여성이 청구하면 월 1일의 생리휴가를 주며 위반하면 500만원 이하 벌금이다":"생리휴가는 청구해야 주어지는 무급이 아니라 월 1일 보장되는 휴가이며 위반하면 벌금이 따릅니다.","여자의 근로는 특별한 보호를 받고 고용·임금·근로조건에서 부당한 차별을 받지 않는다":"헌법은 여자에게 특별한 보호를 주는 동시에 고용·임금·근로조건에서 차별받지 않을 권리를 보장합니다.","연금은 55세 이상이고 가입기간 10년 이상인 가입자에게 지급기간 5년 이상으로 준다":"연금은 55세 이상이면서 가입기간 10년 이상인 가입자에게 5년 이상 지급합니다.","연봉제도 매월 지급 원칙이 적용되고, 임시 임금과 1개월을 넘는 기간의 출근 성적에 따른 정근수당 등은 예외다":"연봉제도 매월 지급 원칙이 적용되고 임시 임금이나 1개월 넘는 근속 수당은 예외입니다.","연소자의 근로도 특별한 보호를 받는다":"연소자의 근로도 헌법상 특별한 보호의 대상입니다.","연장근로와 야간근로(오후 10시~오전 6시)에는 통상임금의 100분의 50 이상을 가산한다":"연장근로와 오후 10시부터 오전 6시까지의 야간근로에는 통상임금의 100분의 50 이상을 더 줍니다.","연장·휴일·야간근로 임금과 가산임금은 최저임금에 산입하지 않는다":"연장·휴일·야간근로에 붙는 가산임금은 기본급 성격이 아니어서 최저임금 비교에서 제외합니다.","연차휴가권은 1년 근로를 마친 다음 날 생기고, 사용 전에 퇴직해도 미사용 수당 청구권은 남으며 소멸시효는 3년이다":"연차휴가는 1년 근로를 채운 다음 날 생기고 미사용수당은 퇴직 후에도 3년 동안 청구할 수 있습니다.","연차휴가 임금은 시간급, 출산전후휴가 임금은 일급 통상임금이 기준이다":"단시간근로자의 휴가 임금은 휴가별 기준이 달라 연차는 시간급, 출산휴가는 일급 통상임금으로 계산합니다.","영업양도는 조직화된 업체를 동일성을 유지한 채 일체로 이전하는 것이고, 일부 재산을 남겨도 종래 조직이 유지되면 영업양도다":"영업양도는 조직화된 업체를 동일성을 유지한 채 통째로 넘기는 것이며 일부 재산이 남아도 조직이 유지되면 해당합니다.","영유아 사망 등의 통지를 받으면 사업주는 통지받은 날부터 30일 이내로 근무개시일을 지정해 알린다":"영유아가 사망하는 등의 사유가 생기면 사업주가 통지를 받은 날부터 30일 이내로 근무개시일을 정해 알려 줍니다.","우리사주는 조합원 의사와 무관하게 할당할 수 없고, 조합 규약 제정·변경은 조합원총회 의결을 거치며 지배관계회사에서 취득자금을 빌릴 수 있다":"우리사주는 조합원의 뜻에 맞춰 할당하고 규약 변경은 총회 의결을 거치며 지배관계회사에서 자금을 빌릴 수 있습니다.","운영위원회는 위원장 포함 10명 이상 15명 이내로 하고 근로자 대표 위원과 사용자 대표 위원 수를 같게 한다":"기금제도 운영위원회는 10명에서 15명 사이로 근로자 측과 사용자 측 위원 수가 같습니다.","위원 임기는 3년이고 연임할 수 있으며 임기가 끝나도 후임자가 정해질 때까지 직무를 수행한다":"위원 임기는 3년이며 연임할 수 있고 후임자가 정해질 때까지 직무를 계속합니다.","위원회가 요청받은 날부터 90일 이내에 의결안 제출 · 장관이 결정이 어렵다고 보면 20일 이내에 이유를 밝혀 10일 이상의 기간을 정해 재심의 요청":"위원회는 요청받은 날부터 90일 안에 의결안을 내고 장관이 어렵다고 보면 20일 안에 이유를 밝혀 10일 이상 기간으로 재심의를 요청합니다.","위원회는 고용노동부에 두고 근로자위원·사용자위원·공익위원 각 9명으로 구성한다":"위원회는 근로자·사용자·공익위원 세 측이 각각 9명으로 구성되어 같은 수로 균형을 이룹니다.","위험성평가는 유해·위험 요인을 찾아 부상·질병으로 이어질 위험성의 크기가 허용 가능한 범위인지 평가하는 것이고, 작업환경측정은 측정계획을 세워 시료를 채취·분석·평가하는 것이다":"위험성평가는 유해·위험 요인을 찾아 위험성이 허용 가능한 범위인지 가리는 것이고 작업환경측정은 시료를 채취·분석·평가하는 것입니다.","유급휴일과 연차휴가의 임금은 파견사업주가 지급하고, 1주 1회 이상 유급휴일 보장과 수유시간 부여는 사용사업주가 한다":"파견에서는 임금 성격의 휴가 비용은 파견사업주가, 현장에서 보장할 휴일과 수유시간은 사용사업주가 맡습니다.","유료소개사업자는 구인자에게서 선급금을 받지 못하고 등록증을 대여하지 못하며 결혼중개업·숙박업 등을 겸업하지 못한다":"유료소개사업자는 구인자 선급금 수령, 등록증 대여, 결혼중개·숙박업 겸업이 모두 금지됩니다.","유산 경험이 있거나 만 40세 이상이거나 유산·사산 위험이 있다는 진단서를 내면 출산 전 어느 때라도 나누어 쓸 수 있다":"유산·사산 위험이 있는 사람은 출산 전에도 휴가를 나눠 쓸 수 있도록 허용해 건강을 보호합니다.","의사인 근로감독관이나 위촉받은 의사는 취업 금지 질병 의심자를 검진한다":"의사인 근로감독관이나 위촉된 의사는 취업이 금지된 질병이 의심되는 사람을 검진합니다.","이 법 관련 분쟁의 입증책임은 사업주가 부담한다(각자 부담 X)":"이 법 관련 분쟁의 입증책임은 사업주가 지며 각자 부담하는 것이 아닙니다.","이 법은 산재보험법이 적용되는 사업에 적용하고 국가와 지방자치단체가 직접 하는 사업에는 적용하지 않는다":"임금채권보장법은 산재보험법이 적용되는 사업에 적용되며 국가와 지방자치단체의 직접 사업은 제외됩니다.","이 법의 근로자는 사업주에게 고용된 사람과 취업할 의사를 가진 사람이다":"남녀고용평등법의 근로자는 사업주에게 고용된 사람과 취업할 의사를 가진 사람까지 포함합니다.","이 법의 사업주는 근로자를 사용하여 사업을 하는 자이며 근기법상 사용자와 범위가 다르다":"이 법의 사업주는 근로자를 쓰는 자로 근로기준법상 사용자와 범위가 다릅니다.","인가를 받기 전에 근로자대표와 성실하게 협의해야 하며 협의가 인가를 대신하지 못한다":"인가를 받기 전 근로자대표와의 성실한 협의가 필요하지만 협의만으로 인가를 대신하지는 못합니다.","인사명령은 원칙적으로 사용자의 고유권한이고 전직의 정당성은 업무상 필요와 생활상 불이익을 비교하여 판단한다":"인사명령은 사용자의 고유권한이며 전직은 업무상 필요와 근로자의 생활상 불이익을 비교해 정당성을 판단합니다.","인사처분에 노조 사전 동의를 얻도록 한 단체협약 조항도 유효하며 대기발령은 사유가 정당해도 기간이 합리적 범위 안이어야 한다":"노조 사전 동의를 인사처분의 조건으로 정한 단체협약도 유효하고 대기발령은 기간이 합리적이어야 합니다.","일부 집단에만 불리해도 다른 집단에 적용이 예상되면 그 집단까지 포함한 전체가 동의 주체다":"일부 집단에만 불리해 보여도 다른 집단에 적용될 여지가 있으면 그 집단을 포함한 전체가 동의 주체입니다.","일시금은 연금 요건을 못 갖추거나 일시금을 원하는 가입자에게 준다":"연금 요건을 못 갖췄거나 일시금을 원하는 가입자에게는 일시금으로 줍니다.","일용근로자의 평균임금은 고용노동부장관이 정하는 금액으로 하고, 지급의무가 확정된 경영평가성과급은 평균임금에 들어간다":"일용근로자는 장관이 정한 금액을 평균임금으로 하고 지급의무가 확정된 경영평가성과급은 평균임금에 들어갑니다.","일정 규모 이상(보험업 등은 상시 300명 이상) 사업주는 안전보건관리규정을 작성하여 게시하고 근로자에게 알린다":"일정 규모 이상 사업주는 안전보건관리규정을 작성해 게시하고 근로자에게 알리며 보험업 등은 상시 300명 이상입니다.","일정 규모 이상 해고는 고용노동부장관에게 신고하고, 3년 이내 같은 업무에 채용할 때 해고자를 우선 재고용하며 생계안정·재취업 지원은 정부가 우선 조치한다":"일정 규모 이상의 해고는 장관에게 신고하고 3년 이내 같은 업무 채용 시 해고자를 먼저 재고용합니다.","일·주·월 단위로 정하면 시간급으로도 표시한다":"일·주·월 단위로 정하면 비교 편의를 위해 시간급으로도 나타냅니다.","일할 환경에 관한 권리도 근로의 권리에 들어간다":"일할 환경에 관한 권리도 근로의 권리에 포함되어 단순히 일자리를 얻는 권리에 그치지 않습니다.","임금, 소정근로시간, 주휴일, 연차 유급휴가 등은 근로계약 체결 때 명시하고 임금의 구성항목·계산방법·지급방법, 소정근로시간, 휴일, 연차휴가는 서면으로 교부한다":"임금, 소정근로시간, 주휴일, 연차휴가는 계약 때 명시하고 임금 구성과 근로시간, 휴일은 서면으로 건네야 합니다.","임금 대신 사용자의 제3자 채권을 양도하기로 한 약정은 원칙적으로 무효다":"사용자가 임금 대신 제삼자에 대한 채권을 넘겨주는 약정은 원칙적으로 무효입니다.","임금보전방안 강구 의무는 탄력적 근로시간제에만 있다":"임금보전방안을 마련할 의무는 탄력적 근로시간제에만 있고 선택적 근로시간제에는 없습니다.","임금은 통화로 직접 근로자에게 전액을 매월 1회 이상 일정한 날짜를 정하여 지급한다":"임금은 통화로, 직접, 전액, 매월 1회 이상 일정한 날에 주는 것이 원칙입니다.","임금채권보장기금은 고용노동부장관이 설치·관리·운용하고 심의위원회는 고용노동부에 둔다(근로복지공단 X)":"기금을 설치·운용하는 주체와 심의위원회 소속은 모두 고용노동부이며 근로복지공단이 아닙니다.","임산부는 도덕상 또는 보건상 유해·위험한 사업에 사용하지 못하고, 18세 미만인 사람도 같다(정신병원 업무 등)":"임산부와 18세 미만자는 도덕상·보건상 유해하거나 위험한 사업에 쓰지 못합니다.","임산부 사용 금지 직종에는 발급하지 않으며 분실하면 사용자가 재교부를 신청하고 본인 동의는 요건이 아니다":"임산부를 쓸 수 없는 직종에는 취직인허증을 내주지 않으며 분실 시 재교부는 사용자가 신청합니다.","임산부 정기건강진단 시간을 청구하면 허용하고, 생후 1년 미만 유아를 가진 여성이 청구하면 1일 2회 각 30분 이상의 유급 수유시간을 준다":"임산부는 검진 시간을 보장받고 영아를 둔 여성은 유급 수유시간을 하루 두 번 받습니다.","임시건강진단은 고용노동부장관이 명하고 산업보건의가 명하는 것이 아니다":"임시건강진단을 명하는 주체는 고용노동부장관이며 산업보건의에게 그 권한이 있지 않습니다.","임신 중 유산·사산 위험이 있으면 휴직개시예정일 7일 전까지 신청할 수 있다":"임신 중 유산·사산 위험이 있으면 개시 예정일 7일 전까지 신청하는 등 예외적으로 빠르게 신청할 수 있습니다.","임신 중인 여성이 1일 소정근로시간을 유지하며 업무 시작·종료 시각 변경을 신청하면 허용한다(산후 1년 X)":"임신 중 여성이 소정근로시간을 유지하며 업무 시작·종료 시각 변경을 신청하면 허용해야 하며 산후 1년은 대상이 아닙니다.","작성·변경 권한은 원칙적으로 사용자에게 있고 해석은 문언의 객관적 의미에 따른다":"취업규칙은 사용자가 만들고 고치며 해석할 때는 문언이 가진 객관적 의미를 따릅니다.","작성·변경 시 과반수 노동조합이 있으면 그 노조의, 없으면 근로자 과반수의 의견을 듣는다":"취업규칙을 만들거나 바꿀 때는 과반수 노조가 있으면 그 노조, 없으면 근로자 과반수의 의견을 듣습니다.","잠함·잠수 등 고기압 작업 근로자에게는 1일 6시간, 1주 34시간을 넘는 근로를 시키지 못한다(5시간 X)":"고기압 작업 근로자에게는 1일 6시간, 1주 34시간을 넘는 근로를 시킬 수 없으며 5시간이 아닙니다.","장관이 매년 8월 5일까지 최저임금을 결정하고 지체 없이 고시":"최저임금은 장관이 매년 8월 5일까지 결정하고 곧바로 고시하는 일정을 따릅니다.","재직 근로자 대지급금은 하나의 사업에서 1회만 지급한다":"재직 중인 근로자가 받는 대지급금은 같은 사업에서 한 번만 받을 수 있습니다.","적극적 고용개선조치는 현존하는 남녀 간 고용차별을 없애거나 고용평등을 촉진하려고 잠정적으로 특정 성을 우대하는 조치다":"적극적 고용개선조치는 고용차별을 없애기 위해 잠정적으로 특정 성을 우대하는 조치입니다.","적립금운용위원회 구성 의무는 상시 300명 이상 사업에 있다(100명 X)":"적립금운용위원회는 규모가 큰 상시 300명 이상 사업에 설치 의무가 있습니다.","적정임금 보장의 주체는 국가이며 ‘사용자’로 바꾼 선지가 출제됐다":"적정임금을 보장할 노력의 주체는 사용자가 아니라 국가이므로 주체를 바꾼 문장은 틀립니다.","전문위원회는 근로자·사용자·공익위원 각 5명 이내 같은 수로 구성하고, 관계 행정기관 공무원 중 3명 이내의 특별위원을 둘 수 있다":"전문위원회도 세 측이 같은 수로 5명 이내씩 구성하며 관계 공무원 3명 이내를 특별위원으로 둘 수 있습니다.","전차금이나 근로를 조건으로 한 전대채권과 임금을 상계하지 못하고, 강제 저축이나 저축금 관리 계약도 금지된다":"전차금과 임금을 상계하거나 강제로 저축하게 하는 계약도 금지됩니다.","정년퇴직자에게 기간제 재고용 기대권이 인정되는 경우도 같다":"정년퇴직자에게 재고용 기대권이 인정되는 경우도 갱신 기대권과 같게 취급합니다.","정산기간은 1개월 이내, 신상품·신기술 연구개발 업무는 3개월 이내다":"선택적 근로시간제 정산기간은 기본 1개월 이내이며 연구개발 업무는 3개월까지로 더 깁니다.","정신 또는 신체 장애로 근로능력이 현저히 낮은 사람은 사용자가 고용노동부장관의 인가를 받아야 적용에서 뺄 수 있다":"장애로 근로능력이 크게 낮은 사람은 사용자가 장관 인가를 받아야 최저임금 적용에서 뺄 수 있습니다.","제105호(강제노동 철폐)는 비준하지 않았으므로 국내 법원이 아니다":"강제노동 철폐 협약은 비준하지 않아 국내 법원이 되지 못합니다.","조정안은 특별한 사유가 없으면 60일 이내에 제시 · 조정에는 적절한 배상이 포함될 수 있고, 중재결정서에는 관여한 위원 전원이 서명·날인한다(관계당사자 서명 X)":"조정안은 60일 안에 제시하고 배상이 포함될 수 있으며 중재결정서에는 관여한 위원 전원이 서명·날인합니다.","중대재해는 사망자 1명 이상, 3개월 이상 요양이 필요한 부상자가 동시에 2명 이상, 부상자 또는 직업성 질병자가 동시에 10명 이상 발생한 재해다":"중대재해는 사망 1명 이상이거나 중상자 또는 직업성 질병자가 기준 수 이상 동시에 생기는 재해입니다.","중소기업퇴직연금기금제도는 근로복지공단이 운영한다(고용노동부 X)":"중소기업퇴직연금기금제도는 고용노동부가 아니라 근로복지공단이 운영합니다.","중앙노동위원회 재심판정서를 송달받은 날부터 15일 이내에 행정소송":"중앙노동위원회 재심판정서를 받은 날부터 15일 안에 행정소송을 제기해야 합니다.","중앙노동위원회 판정 취소소송에서는 기초 사실이 같으면 노동위원회 단계에서 주장하지 않은 사유도 주장할 수 있다":"소송에서는 기초 사실이 같다면 노동위원회에서 내세우지 않은 사유도 새로 주장할 수 있습니다.","지급한 장관은 그 금액 한도에서 근로자의 권리를 대위하고 근기법상 우선변제권도 대위된 권리에 존속하며 대지급금을 반환받을 권리는 3년간 행사하지 않으면 시효로 소멸한다":"지급한 장관은 그 금액 한도에서 근로자의 권리를 대위하며 반환받을 권리는 3년 지나면 시효로 소멸합니다.","지도사는 고용노동부장관에게 등록하고 직무 서류에 기명·날인하거나 서명하며 고의·과실로 의뢰인에게 손해를 입히면 배상한다":"지도사는 장관에게 등록하고 서명·날인하는 서류에 책임을 지며 의뢰인에게 손해를 입히면 배상합니다.","지방노동위원회 결정에 불복하면 통지받은 날부터 10일 이내에 중앙노동위원회에 재심 신청":"지방노동위원회 결정이 마음에 들지 않으면 통지받은 날부터 10일 안에 중앙노동위원회에 재심을 청구해야 합니다.","직무 성격상 특정 성이 불가피하게 요구되면 차별이 아니다":"직무의 성격상 특정 성이 꼭 필요하면 정당한 이유가 있어 차별로 보지 않습니다.","직업성 질병자 2명은 중대재해가 아니다":"직업성 질병자가 동시에 2명 나온 것은 중대재해 기준에 못 미칩니다.","직업적성검사는 구직자 동의가 있어야 하고, 18세 미만 구직자를 소개할 때는 친권자나 후견인의 취업동의서를 받는다":"검사는 구직자 동의가 있어야 하고 18세 미만자를 소개할 때는 친권자 등의 취업동의서가 필요합니다.","징계사유로 삼지 않은 비위라도 평소 소행·근무성적·전후 비위 사실은 양정 참작자료가 된다":"징계사유로 삼지 않은 비위라도 평소 행실과 근무성적은 징계 양정의 참작자료가 됩니다.","차별에 명백한 고의가 있거나 차별이 반복되면 손해액의 3배를 넘지 않는 범위에서 배상을 명할 수 있다":"고의가 명백하거나 차별이 되풀이되면 노동위원회가 손해액의 3배까지 배상을 명할 수 있습니다.","차별적 처우를 받거나 성희롱 신고·피해를 이유로 불리한 처우(감봉 등)를 받거나 사업주가 피해자 보호조치를 하지 않으면 노동위원회에 시정을 신청할 수 있다":"차별적 처우나 성희롱 신고에 따른 불리한 처우, 보호조치 미이행이 있으면 노동위원회에 시정을 신청할 수 있습니다.","천재·사변 등 부득이한 사유로 이행이 어려우면 직권으로 그 사유가 없어진 뒤에 부과할 수 있고, 납부하지 않으면 독촉 후 국세 체납처분의 예에 따라 징수한다":"부득이한 사유로 이행이 어려우면 사유가 없어진 뒤에 부과할 수 있고 납부하지 않으면 국세 체납처분의 예로 징수합니다.","체결 후 이 사항을 변경할 때에도 명시하여야 한다":"계약을 맺은 뒤 이 사항을 바꿀 때도 다시 명시해야 합니다.","초과근로는 합의한 경우에만 시킬 수 있다":"단시간근로자에게 초과근로는 합의가 있을 때만 시킬 수 있습니다.","초과지급된 임금의 반환채권으로 하는 상계와 근로자의 자유로운 의사에 따른 동의가 객관적으로 인정되는 상계는 허용된다":"잘못 더 준 임금을 돌려받는 채권이나 근로자가 자유롭게 동의한 상계는 허용됩니다.","최저임금에 못 미치는 임금을 정한 부분은 무효이고 최저임금액과 같은 임금을 정한 것으로 본다":"기준에 못 미친 약정은 그 부분이 무효가 되어 법정 최저임금액을 임금으로 받은 것으로 간주됩니다.","최저임금은 근로자의 생계비, 유사 근로자의 임금, 노동생산성 및 소득분배율 등을 고려하여 정하고 사업의 종류별로 구분할 수 있다":"최저임금은 생계비 같은 여러 기준을 반영해 정하고 필요하면 업종별로 다르게 정할 수 있습니다.","최종 3개월분 임금과 휴업수당, 최종 3년분 퇴직급여 등이 대지급금 범위다":"대지급금은 최종 3개월분 임금과 휴업수당, 최종 3년분 퇴직급여 등을 범위로 합니다.","최초 구제명령일을 기준으로 매년 2회 범위에서 반복 부과할 수 있고 2년을 넘지 못한다":"이행강제금은 최초 구제명령일을 기준으로 매년 2회 범위에서 반복 부과하되 2년을 넘기지 못합니다.","출산 전과 후를 통하여 90일(한 번에 둘 이상 임신하면 120일)을 주고 출산 후에 45일(다태아 60일) 이상이 되게 한다":"출산전후휴가는 출산 전후를 합쳐 90일이고 한 번에 둘 이상을 임신하면 120일이며 출산 후에 45일 이상이 되도록 합니다.","출산전후휴가 기간을 산정기간에 포함한다는 선지는 틀렸다":"출산전후휴가 기간은 산정기간에서 빼는 대상이라 포함한다는 설명은 틀립니다.","출입국관리법 위반으로 처벌받은 사용자는 3년간 고용을 제한할 수 있고(5년·6년·‘하여야’ X), 고용허가가 취소되면 15일 이내에 근로계약을 끝낸다":"출입국관리법 위반 사용자는 3년간 고용을 제한할 수 있고 고용허가가 취소되면 15일 이내에 근로계약을 끝냅니다.","취업규칙보다 유리한 근로계약은 우선 적용되고, 집단적 동의로 불리하게 바뀐 취업규칙도 개별 동의가 없으면 기존의 유리한 근로계약을 누르지 못한다":"취업규칙보다 유리한 근로계약이 우선하고 집단 동의로 취업규칙을 낮춰도 개별 동의 없이 유리한 계약을 누르지 못합니다.","취업규칙에서 정한 기준에 미달하는 근로계약 부분은 무효이고 무효인 부분은 취업규칙 기준에 따른다":"취업규칙이 정한 기준에 못 미치는 근로계약 부분은 무효가 되고 그 자리에 취업규칙 기준이 들어갑니다.","취업규칙으로 시작·종료 시각을 근로자 결정에 맡긴 근로자를 대상으로 근로자대표와 서면 합의하여 도입하고 표준근로시간을 정한다":"선택적 근로시간제는 시작·종료 시각을 근로자에게 맡기는 취업규칙을 두고 근로자대표와 서면 합의하여 표준근로시간을 정합니다.","취업규칙으로 정하고 특정 주 48시간을 넘지 못하며 특정 일의 한도 규정은 없다":"이 단위는 취업규칙으로 정할 수 있고 특정 주 상한은 48시간이며 특정 일에는 한도가 따로 없습니다.","취업규칙을 근로자에게 불리하게 바꾸려면 과반수 노조, 없으면 근로자 과반수(회의 방식에 의한 집단적 동의)의 동의를 받는다":"불리하게 바꾸려면 과반수 노조나 근로자 과반수가 회의 방식으로 집단 동의를 해야 합니다.","취업규칙의 해고사유에 해당하더라도 해고에는 정당한 이유가 있어야 한다":"취업규칙에 해고사유가 있어도 해고에는 별도로 정당한 이유가 있어야 합니다.","취직인허증을 갖추어 두면 두 서류를 갖춘 것으로 본다":"취직인허증을 갖춰 두면 위의 두 서류를 갖춘 것으로 인정됩니다.","측정은 작업환경측정기관에 위탁할 수 있고 시료 분석만 위탁할 수도 있다":"작업환경측정은 전문 기관에 맡길 수 있고 시료 분석만 위탁하는 것도 가능합니다.","친권자, 후견인 또는 고용노동부장관은 근로계약이 미성년자에게 불리하다고 인정하면 해지할 수 있다":"미성년자에게 불리한 근로계약은 친권자, 후견인, 고용노동부장관이 해지할 수 있습니다.","친권자나 후견인은 미성년자의 근로계약을 대리할 수 없고, 미성년자 동의가 있어도 마찬가지다":"미성년자 본인이 일하는 계약이므로 법정대리인이 대신 맺을 수 없고 본인 동의가 있어도 달라지지 않습니다.","침실 넓이는 1인당 2.5제곱미터 이상이고, 소음·진동이 심한 장소에는 설치하지 못한다":"기숙사 침실은 1인당 2.5제곱미터 이상이어야 하고 소음·진동이 심한 곳에는 설치하지 못합니다.","토지의 경작 등 농림 사업 근로자에게는 근로시간·휴게·휴일 규정을 적용하지 않는다":"농림 사업은 날씨와 계절의 영향을 받아 근로시간·휴게·휴일 규정을 적용하지 않습니다.","퇴직 근로자는 파산선고, 회생절차개시결정, 도산등사실인정이 있으면 도산대지급금을 받는다(회생절차개시 ‘신청’만으로는 안 된다)":"도산대지급금은 파산선고, 회생절차개시결정, 도산등사실인정이 있어야 받으며 회생 신청만으로는 부족합니다.","퇴직금은 계속근로기간 1년에 30일분 이상의 평균임금이다(통상임금 X)":"퇴직금 산정 기준은 통상임금이 아니라 평균임금이고 근속 1년에 30일분 이상입니다.","퇴직금을 미리 정산한 사업주와 외국인근로자 출국만기보험에 가입한 사업주는 부담금을 경감할 수 있다":"퇴직금을 미리 정산했거나 외국인 출국만기보험에 가입한 사업주는 부담금을 경감받을 수 있습니다.","퇴직금을 받을 권리는 3년간 행사하지 않으면 시효로 소멸한다":"퇴직금 청구권은 3년 안에 행사하지 않으면 시효로 사라집니다.","퇴직급여제도는 확정급여형·확정기여형 퇴직연금제도, 중소기업퇴직연금기금제도, 퇴직금제도를 말한다(중소기업퇴직연금기금제도는 2021 개정으로 추가)":"퇴직급여제도에는 두 종류의 퇴직연금과 기금제도, 퇴직금제도가 있고 기금제도는 2021년에 더해졌습니다.","퇴직급여제도를 설정하거나 다른 종류로 변경하려면 과반수 노조가 있으면 그 노조, 없으면 근로자 과반수의 동의를 받는다":"제도를 설정하거나 종류를 바꾸려면 과반수 노조, 없으면 근로자 과반수의 동의를 받아야 합니다.","퇴직연금사업자는 매년 1회 이상 적립금액과 운용수익률 등을 가입자에게 알린다(매분기 X)":"퇴직연금사업자의 통지 주기는 매년 1회 이상이며 분기마다 해야 하는 것은 아닙니다.","퇴직 후 14일 이내에 지급하되 특별한 사정이 있으면 당사자 합의로 기일을 연장할 수 있다":"퇴직금은 퇴직 후 14일 안에 주되 특별한 사정이 있으면 당사자 합의로 기일을 늘릴 수 있습니다.","파견 대가 내역은 파견사업주에게 요구하며 사용사업관리책임자는 사용사업주가 선임한다":"파견 대가 내역은 계약 당사자인 파견사업주에게 요구하고 현장 책임자인 사용사업관리책임자는 사용사업주가 선임합니다.","파견사업주는 위약금 예정 계약, 고용관계 종료 후 사용사업주 고용을 막는 계약, 명의 대여를 하지 못하고, 파견근로자가 아닌 자기 근로자를 파견하려면 서면으로 알리고 동의를 받는다":"파견사업주는 위약금 예정, 사용사업주 고용 방해 계약, 명의 대여를 하지 못하고 자기 근로자를 파견하려면 서면 고지와 동의가 필요합니다.","파견사업주는 쟁의행위 중인 사업장에 중단된 업무 수행을 위해 파견하지 못하며 근로자대표 동의가 있어도 같다":"쟁의행위로 중단된 업무를 파견근로자로 메우는 것은 근로자대표가 동의해도 금지됩니다.","폐지는 허가가 아니라 신고 사항이고 신고일부터 허가가 효력을 잃는다":"파견사업 폐지는 허가가 아닌 신고 사항이며 신고일부터 허가가 효력을 잃습니다.","피해자는 ‘다른 근로자’이고 사용자는 피해자로 규정되어 있지 않다":"피해자는 다른 근로자로 규정되어 있어서 사용자는 피해자가 될 수 없습니다.","하나의 사업에서 급여와 부담금 산정방법을 차등하면 안 된다":"퇴직급여제도는 같은 사업 안에서 근로자별로 급여나 부담금 산정을 달리하면 안 됩니다.","한국은 2021년 제87호(결사의 자유), 제98호(단결권·단체교섭), 제29호(강제노동) 협약을 비준했다":"한국은 2021년에 결사의 자유, 단결권·단체교섭, 강제노동 협약을 비준해 국내법과 같은 효력을 가집니다.","해고 50일 전까지 과반수 노조(없으면 근로자 과반수 대표)에게 통보하고 성실하게 협의한다":"해고 50일 전까지 과반수 노조나 근로자 과반수 대표에게 알리고 성실히 협의해야 합니다.","해고는 묵시적 의사표시로도 할 수 있고, 근로자의 사직 의사표시는 원칙적으로 근로계약을 끝내는 해약고지로 본다":"해고는 묵시적 의사표시로도 가능하고 근로자의 사직 의사표시는 원칙적으로 해약고지로 봅니다.","해고된 근로자가 해고 등이 있었던 날부터 3개월 이내에 노동위원회에 구제신청 · 노동조합은 신청인이 될 수 없다":"부당해고 구제신청은 해고일로부터 3개월 안에 근로자가 하며 노동조합은 신청인이 될 수 없습니다.","해고사유와 시기는 서면으로 알려야 하지만 상시 4명 이하 사업에는 이 서면통지 규정이 적용되지 않는다":"서면 통지 의무는 4명 이하 사업장에는 적용되지 않아 해고사유와 시기를 구두로 알려도 됩니다.","해고 회피 노력, 합리적이고 공정한 대상자 선정 기준이 함께 필요하며 요건 충족 여부는 개별 사정을 종합하여 판단한다":"경영상 해고에는 해고 회피 노력과 합리적이고 공정한 대상자 선정 기준이 함께 필요하며 개별 사정을 종합해 판단합니다.","해약권이 유보된 근로계약이 성립하므로 내정 취소에도 해고 제한(제23조)이 적용된다":"채용내정은 해약권이 유보된 근로계약이 성립한 것이라 내정을 취소하면 해고 제한이 적용됩니다.","행정기관 내부의 사무처리준칙에 그치는 고시는 법원으로 보지 않는다":"고시가 행정기관 내부 사무처리준칙에 그치면 국민을 구속하지 못해 법원으로 보지 않습니다.","허가 유효기간은 3년이고 갱신허가 유효기간은 종전 허가의 유효기간이 끝나는 날의 다음 날부터 3년이다(2년 X)":"허가 유효기간은 3년이고 갱신허가는 종전 유효기간이 끝나는 날 다음 날부터 3년입니다.","허용하지 않으면 사유를 서면으로 알리고, 나누어 쓸 수 있으며 끝나면 같은 업무나 같은 수준 임금의 직무로 복귀시키고 단축 기간은 평균임금 산정기간에서 뺀다":"허용하지 않을 때는 사유를 서면으로 알리고 끝나면 같은 업무나 같은 임금 직무로 복귀시키며 단축 기간은 평균임금 산정에서 뺍니다.","확정기여형을 설정한 사용자는 매년 1회 이상 가입자의 연간 임금총액의 12분의 1 이상을 현금으로 가입자 계정에 납입한다":"확정기여형에서 사용자는 해마다 연간 임금총액의 12분의 1 이상을 가입자 계정에 현금으로 넣습니다.","확정된 구제명령 불이행은 1년 이하 징역 또는 1천만원 이하 벌금이고 노동위원회의 고발이 있어야 공소를 제기하며 검사는 노동위원회에 고발을 요청할 수 있다(근로감독관 X, ‘하여야’ X)":"확정된 구제명령을 어기면 1년 이하 징역 또는 1천만원 이하 벌금이며 노동위원회 고발이 있어야 공소를 제기합니다.","확정된 시정명령을 사용자가 이행하지 않으면 근로자는 고용노동부장관에게 신고할 수 있고, 장관은 직접 사용자에게 시정을 요구할 수도 있다":"확정된 시정명령을 지키지 않으면 근로자가 신고하고 장관이 사용자에게 시정을 요구할 수 있습니다.","회의는 재적위원 과반수 출석과 출석위원 과반수 찬성으로 의결한다":"위원회는 재적위원 과반수가 출석하고 그중 과반수가 찬성하면 의결됩니다.","휴업수당도 임금이고, 근로 의사가 있는데 취업이 거부된 경우와 경영상 대기발령도 휴업에 포함된다":"휴업수당도 임금이며 일할 의사가 있는데 취업이 거부되거나 경영상 대기발령을 한 경우도 휴업에 포함됩니다.","휴일근로는 8시간 이내 100분의 50, 8시간 초과분은 100분의 100 이상을 가산하고, 기준은 평균임금이 아니라 통상임금이다":"휴일근로 가산은 8시간까지와 초과분으로 나누고 가산 기준은 평균임금이 아니라 통상임금입니다.","휴직개시예정일 전날까지 계속근로 6개월 미만인 근로자는 사업주가 허용하지 않을 수 있다":"휴직 개시 전날까지 6개월을 채우지 못한 근로자에게는 사업주가 육아휴직을 허용하지 않을 수 있습니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
